-- afghan-bolani.json
insert into sim.dish (slug, doc) values (
  $sd$afghan-bolani$sd$,
  $sd${"title":"Bolani","description":"Thin unleavened flatbreads folded over a potato and leek filling and cooked in a nearly dry pan until they blister. Eaten hot with garlic yogurt, cut into wedges. Makes six large breads.\n\nThe filling must be cold and dry before it meets the dough. Warm filling steams from the inside and splits the seam in the pan, which is the only real way this goes wrong.","cuisine":"Afghan","category":"Snack","difficulty":"medium","prep_minutes":45,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":350,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":220,"unit":"ml","name":"water","note":"warm","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"vegetable oil","note":null,"is_optional":false,"food_id":null}]},{"name":"Potato and leek filling","ingredients":[{"quantity":500,"unit":"g","name":"potatoes","note":"boiled and mashed dry, no butter","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"leeks","note":"white and pale green only, sliced very thin","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"cilantro","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"green chili","note":"seeded and finely chopped","is_optional":true,"food_id":null},{"quantity":1,"unit":"tsp","name":"coriander","note":"ground","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"vegetable oil","note":null,"is_optional":false,"food_id":null}]},{"name":"Garlic yogurt","ingredients":[{"quantity":250,"unit":"g","name":"yogurt","note":"plain","is_optional":false,"food_id":null},{"quantity":1,"unit":"clove","name":"garlic","note":"crushed to a paste","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"dried mint","note":null,"is_optional":false,"food_id":null},{"quantity":0.25,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Mix the flour and salt, work in the water and the oil, and knead until the dough is smooth and only just tacky.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Cover it and leave it on the counter to relax.","duration_minutes":30,"temperature":null,"tip":"This rest is what lets you roll it thin enough to see the bench through. Skip it and the dough fights back at every pass."}]},{"name":"Filling","steps":[{"text":"Soften the leeks in the oil over a low heat until they collapse but keep their green.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Fold the leeks through the mashed potatoes with the cilantro, green chili, coriander, salt and black pepper, then spread it over a plate to cool completely.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Rolling and frying","steps":[{"text":"Divide the dough into six, roll each piece into a thin round about 25 cm across, and spread the filling over one half only, leaving a clear border at the edge.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fold the bare half over, press the rim flat with your fingertips, and seal it properly with the tines of a fork.","duration_minutes":null,"temperature":null,"tip":"Any air trapped inside will find the weakest point of that seal and blow it open. Press from the fold outwards to push it out first."},{"text":"Cook each one in a barely oiled pan over a medium heat until blistered and brown in patches on both sides.","duration_minutes":4,"temperature":null,"tip":null}]},{"name":"To serve","steps":[{"text":"Beat the yogurt with the garlic, dried mint and salt, and put it on the table with the bolani cut into wedges while they are still hot.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Pumpkin","{title}, Baked Not Fried"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- american-spiced-nuts.json
insert into sim.dish (slug, doc) values (
  $sd$american-spiced-nuts$sd$,
  $sd${"title":"Rosemary Spiced Nuts","description":"Mixed nuts roasted with butter, rosemary, and cayenne, tossed while still hot so the seasoning sticks. Twelve servings, gone in twenty minutes.\n\nKeeps two weeks airtight, and re-crisps in a low oven for five minutes if it softens.","cuisine":"American","category":"Snack","difficulty":"easy","prep_minutes":10,"cook_minutes":15,"servings":12,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"mixed nuts","note":"unsalted — pecans, cashews, almonds","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"butter","note":"melted","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"rosemary","note":"chopped fine","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"cayenne","note":"adjust to taste","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Spread the mixed nuts on a tray and roast until they smell toasted and have taken a little colour.","duration_minutes":15,"temperature":"350°F","tip":"Shake the tray halfway. Nuts go from perfect to burnt in about ninety seconds."},{"text":"Combine the melted butter, rosemary, brown sugar, salt, and cayenne in a large bowl.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Tip the hot nuts straight into the bowl and toss until every one is coated.","duration_minutes":null,"temperature":null,"tip":"Hot is doing the work here — the rosemary fries slightly against the nuts and the sugar just melts."},{"text":"Spread back out to cool and crisp before serving.","duration_minutes":20,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["Holiday {title}","Maple {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- argentine-chimichurri.json
insert into sim.dish (slug, doc) values (
  $sd$argentine-chimichurri$sd$,
  $sd${"title":"Chimichurri","description":"Raw parsley, oregano, garlic, and vinegar loosened with oil. Chopped by hand, never blended — a food processor turns it into green paste.\n\nMakes about a cup. Keeps a week refrigerated, though the parsley darkens after day two.","cuisine":"Argentine","category":"Sauce","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1,"unit":"cup","name":"flat-leaf parsley","note":"packed, chopped fine by hand","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"dried oregano","note":null,"is_optional":false,"food_id":null},{"quantity":6,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"red chilli","note":"minced; or 1 tsp chilli flakes","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"warm water","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Dissolve the salt in the warm water and add the dried oregano to rehydrate it.","duration_minutes":5,"temperature":null,"tip":"Dried oregano straight into oil stays woody. Water first."},{"text":"Chop the parsley, garlic, and red chilli finely by hand and combine them in a bowl.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Stir in the oregano mixture and the red wine vinegar, then pour in the olive oil and stir once — it should stay loose and separated, not emulsified.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave to sit before using.","duration_minutes":30,"temperature":null,"tip":"It tastes harsh for the first half hour and then settles."}]}],"weight":1.2,"variant_titles":["{title} Rojo","{title} for Steak"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- armenian-spas-soup.json
insert into sim.dish (slug, doc) values (
  $sd$armenian-spas-soup$sd$,
  $sd${"title":"Spas Yogurt Soup","description":"A soup made almost entirely of yogurt, held together with an egg and a spoonful of flour so it never splits, with barley for body and a spoon of mint butter stirred in at the end. Good hot in winter and cold in summer.\n\nCold yogurt straight from the fridge is the usual cause of a curdled pot. Leave it out while the barley cooks and the tempering becomes almost foolproof.","cuisine":"Armenian","category":"Soup","difficulty":"easy","prep_minutes":15,"cook_minutes":45,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":100,"unit":"g","name":"pearl barley","note":"rinsed","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":700,"unit":"g","name":"plain yogurt","note":"full fat, at room temperature","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"egg","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"finely diced","is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"dried mint","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"cilantro","note":"chopped, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Simmer the pearl barley in the water until the grains are tender and have split slightly, then leave it in its cooking liquid.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Whisk the yogurt, egg and flour together in a large bowl until there is not a streak of flour left anywhere.","duration_minutes":null,"temperature":null,"tip":"The egg and the flour are both insurance against splitting. Neither one alone is reliable in a pot this thin."},{"text":"Ladle a cupful of the hot barley liquid into the yogurt while whisking hard, then a second, then a third. The bowl should feel warm rather than hot before it goes anywhere near the stove.","duration_minutes":null,"temperature":null,"tip":"Going the other way — yogurt into the pot — is how it curdles. Always bring the hot to the cool."},{"text":"Pour the tempered mixture back into the pot and bring it up to the laziest simmer, stirring in one direction the whole time. Never let it reach a rolling boil.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Meanwhile soften the onion in the butter in a small pan, then take it off the heat and stir in the dried mint.","duration_minutes":8,"temperature":null,"tip":"Mint added to a hot pan goes dusty and grey. Off the heat it stays green and smells like mint."},{"text":"Stir the mint butter through the soup, season with the salt, and finish each bowl with cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["Chilled {title}","{title} with Bulgur"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- australian-lamingtons.json
insert into sim.dish (slug, doc) values (
  $sd$australian-lamingtons$sd$,
  $sd${"title":"Lamingtons","description":"Day-old sponge cut into cubes, dipped in a thin chocolate icing and rolled in coconut. Makes a 20 cm square tin's worth, which is sixteen generous squares.\n\nThe overnight rest is not about flavour. A fresh sponge is too tender to survive being dipped and it disintegrates into the icing bowl, which is by far the most common way this goes wrong.","cuisine":"Australian","category":"Dessert","difficulty":"medium","prep_minutes":40,"cook_minutes":35,"servings":16,"attribution":null,"ingredient_groups":[{"name":"For the sponge","ingredients":[{"quantity":4,"unit":null,"name":"eggs","note":"at room temperature","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"caster sugar","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"self-raising flour","note":"sifted twice","is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"butter","note":"melted and cooled","is_optional":false,"food_id":null},{"quantity":60,"unit":"ml","name":"milk","note":"lukewarm","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"vanilla extract","note":null,"is_optional":false,"food_id":null}]},{"name":"For the chocolate icing","ingredients":[{"quantity":500,"unit":"g","name":"icing sugar","note":null,"is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"cocoa powder","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":"melted","is_optional":false,"food_id":null},{"quantity":200,"unit":"ml","name":"boiling water","note":null,"is_optional":false,"food_id":null}]},{"name":"To coat","ingredients":[{"quantity":250,"unit":"g","name":"desiccated coconut","note":"fine, not shredded","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The sponge","steps":[{"text":"Beat the eggs and caster sugar until the mixture is pale and thick enough to hold a ribbon on the surface for three seconds.","duration_minutes":8,"temperature":null,"tip":"Every bit of the rise comes from here. Under-whipped eggs give a flat, tight crumb and no amount of raising agent puts it back."},{"text":"Fold in the self-raising flour in three additions, then the melted butter, the milk and the vanilla extract.","duration_minutes":null,"temperature":null,"tip":"Fold, do not stir. Each stroke past the point where the flour disappears costs you height."},{"text":"Pour into a lined square tin and bake until the sponge springs back when pressed in the middle.","duration_minutes":30,"temperature":"350°F","tip":null},{"text":"Cool the sponge completely in the tin, then wrap it and leave it overnight.","duration_minutes":720,"temperature":null,"tip":"A day-old sponge cuts into clean cubes and holds together in the icing. This step is the whole difference between neat lamingtons and a bowl of chocolate crumbs."}]},{"name":"Coating","steps":[{"text":"Trim the crusts and cut the sponge into sixteen even cubes.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Whisk the icing sugar, cocoa powder and melted butter with the boiling water until the icing runs off a spoon in a sheet.","duration_minutes":null,"temperature":null,"tip":"Thinner than looks right. Thick icing drags the sponge apart and sets in ugly ridges."},{"text":"Spread the desiccated coconut in a wide tray. Drop each cube into the icing, lift it out on two forks, let it drip, then roll it through the coconut.","duration_minutes":null,"temperature":null,"tip":"Two forks, one cube at a time, and coconut-side hand kept dry. Wet fingers in the coconut tray turn it into a clumped mess within four cubes."},{"text":"Set the coated cubes on a rack until the icing has firmed up.","duration_minutes":60,"temperature":null,"tip":"If the icing thickens while you work, sit its bowl over a pan of hot water for a minute rather than adding more liquid."}]}],"weight":0.6,"variant_titles":["Raspberry {title}","{title} with Cream","Mini {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- austrian-sachertorte.json
insert into sim.dish (slug, doc) values (
  $sd$austrian-sachertorte$sd$,
  $sd${"title":"Sachertorte","description":"A dense chocolate cake split and sealed with apricot jam, then poured over with a mirror glaze. Baked in a 23 cm springform and cut small, because it is very rich. Whipped cream on the side is not optional in Vienna.\n\nThree separate operations that each want your full attention — cake, jam seal, glaze. Bake a day ahead if you can; the crumb firms up overnight and slices far more cleanly.","cuisine":"Austrian","category":"Dessert","difficulty":"hard","prep_minutes":45,"cook_minutes":55,"servings":12,"attribution":null,"ingredient_groups":[{"name":"For the cake","ingredients":[{"quantity":130,"unit":"g","name":"dark chocolate","note":"around 55%, chopped","is_optional":false,"food_id":null},{"quantity":130,"unit":"g","name":"butter","note":"soft","is_optional":false,"food_id":null},{"quantity":110,"unit":"g","name":"icing sugar","note":null,"is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"eggs","note":"separated","is_optional":false,"food_id":null},{"quantity":110,"unit":"g","name":"caster sugar","note":null,"is_optional":false,"food_id":null},{"quantity":140,"unit":"g","name":"plain flour","note":"sifted","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"vanilla extract","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"For the apricot layer","ingredients":[{"quantity":200,"unit":"g","name":"apricot jam","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"rum","note":null,"is_optional":true,"food_id":null}]},{"name":"For the glaze","ingredients":[{"quantity":200,"unit":"g","name":"dark chocolate","note":"chopped fine","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"caster sugar","note":null,"is_optional":false,"food_id":null},{"quantity":125,"unit":"ml","name":"water","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Cake","steps":[{"text":"Melt the dark chocolate over a pan of steaming water and leave it to come down to barely warm.","duration_minutes":8,"temperature":null,"tip":"Hot chocolate meeting soft butter seizes it into grains. Blood heat on the inside of your wrist is the test."},{"text":"Beat the butter with the icing sugar and the vanilla extract until pale, then beat in the egg yolks one at a time.","duration_minutes":6,"temperature":null,"tip":null},{"text":"Fold the cooled chocolate through the butter mixture.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Whip the egg whites with the salt to soft peaks, then rain in the caster sugar and whip to a meringue that flops over at the tip.","duration_minutes":null,"temperature":null,"tip":"Stiff peaks tear rather than fold, and every tear is a streak of dry white in the finished crumb."},{"text":"Slacken the batter with a third of the meringue, then alternate the rest of the meringue with the sifted plain flour in three additions.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake in a lined 23 cm springform until a skewer comes out with a few damp crumbs clinging to it.","duration_minutes":50,"temperature":"170°C / 340°F","tip":null},{"text":"Cool in the tin for ten minutes, then turn out onto a rack and leave until stone cold.","duration_minutes":60,"temperature":null,"tip":null}]},{"name":"Assembly","steps":[{"text":"Slice the cold cake horizontally into two even layers.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Warm the apricot jam with the rum until it pours, then push it through a sieve to catch the fruit pieces.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Spread half the jam over the cut face, sandwich the cake back together, and paint the rest thinly over the top and sides. Leave it to set to a tacky film.","duration_minutes":20,"temperature":null,"tip":"The jam is not a filling, it is a seal. Skip it and the glaze drags loose crumb around with it as it runs."}]},{"name":"Glaze","steps":[{"text":"Boil the caster sugar with the water to a light syrup.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Off the heat, stir the chopped dark chocolate into the syrup and let it cool until it ribbons off the spoon and coats the back of it.","duration_minutes":null,"temperature":"35°C / 95°F","tip":"Too hot and it runs off in a thin veil; too cool and it sets before it has covered the sides."},{"text":"Stand the cake on a rack over a tray and pour the glaze onto the centre in one continuous movement, letting it find its own way down.","duration_minutes":null,"temperature":null,"tip":"Never touch it with a palette knife. Every mark you make in a poured glaze is permanent."},{"text":"Leave to set at room temperature — the fridge kills the shine.","duration_minutes":120,"temperature":null,"tip":null}]}],"weight":0.4,"variant_titles":["{title} with Whipped Cream","Miniature {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- azerbaijani-pakhlava.json
insert into sim.dish (slug, doc) values (
  $sd$azerbaijani-pakhlava$sd$,
  $sd${"title":"Baku Pakhlava","description":"The Azerbaijani version: a soft enriched dough rolled into eight thin sheets rather than bought filo, layered with cardamom walnuts, glazed with saffron, and drowned in syrup the moment it leaves the oven. Cuts into about twenty diamonds in a 30 cm tin.\n\nA project bake, and the long rest at the end is not optional — cut into it warm and the syrup is still sitting in the bottom of the tin instead of inside the layers.","cuisine":"Azerbaijani","category":"Dessert","difficulty":"hard","prep_minutes":75,"cook_minutes":60,"servings":20,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":500,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"butter","note":"melted and cooled","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"egg yolks","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"sour cream","note":null,"is_optional":false,"food_id":null},{"quantity":80,"unit":"ml","name":"milk","note":"lukewarm","is_optional":false,"food_id":null},{"quantity":7,"unit":"g","name":"active dry yeast","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Walnut filling","ingredients":[{"quantity":500,"unit":"g","name":"walnuts","note":"chopped to rubble, never powdered","is_optional":false,"food_id":null},{"quantity":250,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cardamom","note":"ground","is_optional":false,"food_id":null}]},{"name":"Syrup and finishing","ingredients":[{"quantity":250,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"ml","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"honey","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"saffron threads","note":"steeped in 2 Tbsp hot water","is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"butter","note":"melted, for brushing","is_optional":false,"food_id":null},{"quantity":30,"unit":null,"name":"walnut halves","note":"one for each diamond","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"egg yolk","note":"for the glaze","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The dough","steps":[{"text":"Stir the yeast and the tablespoon of sugar into the lukewarm milk and leave it until the surface is foaming.","duration_minutes":10,"temperature":null,"tip":"If nothing happens in ten minutes the yeast is dead and the whole afternoon is wasted. Find out now."},{"text":"Work the flour, salt, melted butter, egg yolks and sour cream together with the yeast milk, then knead until the dough is soft and stops sticking to your hands.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Cover the bowl and rest it somewhere warm until the dough has relaxed and rolls without springing back.","duration_minutes":60,"temperature":null,"tip":null}]},{"name":"Layering","steps":[{"text":"Mix the walnuts with the sugar and the cardamom.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Divide the dough into eight, and roll each piece to the size of the tin and as thin as you dare.","duration_minutes":null,"temperature":null,"tip":"Roll them all out before you start layering. A sheet left sitting under a towel stays workable; one left on the bench dries into a cracker."},{"text":"Lay a sheet into the buttered tin, brush it with melted butter, and scatter over a seventh of the walnut mixture. Repeat until the sheets and the filling are used up.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Finish with the last sheet, brush the top generously with butter, and chill the tin so the layers firm up before you cut them.","duration_minutes":30,"temperature":null,"tip":"Cold dough cuts cleanly. Warm dough drags, and the diamonds close up again in the oven."}]},{"name":"Baking and syrup","steps":[{"text":"Cut the tin into diamonds all the way down to the base with a long sharp knife, and press a walnut half into the centre of each one.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Whisk the remaining egg yolk with the steeped saffron and its liquid and paint it over the whole surface.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake until the top is a deep amber and the cuts have opened.","duration_minutes":50,"temperature":"180 C / 350 F","tip":null},{"text":"While it bakes, boil the sugar, water and honey together into a light syrup and let it cool to just warm.","duration_minutes":10,"temperature":null,"tip":"Warm syrup onto hot pastry is the pairing that soaks in. Two hot things together makes it soggy, two cold ones makes it sit on the surface."},{"text":"Pour the syrup along every cut the moment the tin comes out of the oven, then leave it alone overnight before lifting out a single piece.","duration_minutes":720,"temperature":null,"tip":null}]}],"weight":0.5,"variant_titles":["{title} with Pistachios","Novruz {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- belgian-liege-waffles.json
insert into sim.dish (slug, doc) values (
  $sd$belgian-liege-waffles$sd$,
  $sd${"title":"Liège Waffles","description":"Not batter but a brioche dough, studded with pearl sugar that half melts into caramel against the iron. Makes ten waffles, and the dough has to rest overnight before it can be handled at all.\n\nPearl sugar is the one thing with no substitute. Crushed sugar cubes dissolve, granulated sugar disappears entirely, and without those crunching pockets this is just a heavy waffle.","cuisine":"Belgian","category":"Dessert","difficulty":"hard","prep_minutes":30,"cook_minutes":20,"servings":10,"attribution":null,"ingredient_groups":[{"name":"For the dough","ingredients":[{"quantity":250,"unit":"g","name":"bread flour","note":null,"is_optional":false,"food_id":null},{"quantity":7,"unit":"g","name":"instant yeast","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"ml","name":"whole milk","note":"lukewarm","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"eggs","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"caster sugar","note":null,"is_optional":false,"food_id":null},{"quantity":175,"unit":"g","name":"butter","note":"very soft, cubed","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"vanilla extract","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"cinnamon","note":null,"is_optional":true,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"To finish","ingredients":[{"quantity":200,"unit":"g","name":"pearl sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"neutral oil","note":"for the iron","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Whisk the instant yeast into the lukewarm whole milk with a spoonful of the caster sugar and leave it until the surface foams.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Work the bread flour, the rest of the caster sugar, the salt, the cinnamon, and the eggs into the yeast milk, then knead until the dough comes cleanly off the side of the bowl.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Add the soft butter three or four cubes at a time, kneading each lot in completely before the next goes near it.","duration_minutes":12,"temperature":null,"tip":"Around the halfway mark the dough will look curdled and hopeless. Keep going — it comes back together in about two minutes."},{"text":"Beat in the vanilla extract, cover the bowl, and leave at room temperature until doubled.","duration_minutes":90,"temperature":null,"tip":null},{"text":"Knock the dough back, cover it tightly, and refrigerate overnight.","duration_minutes":720,"temperature":null,"tip":"The cold rest is what makes this dough portionable. At room temperature it is a butter slick you cannot get off your hands."}]},{"name":"Baking","steps":[{"text":"Divide the cold dough into ten pieces and knead the pearl sugar into each one by hand, roughly a heaped spoonful per piece.","duration_minutes":null,"temperature":null,"tip":"Fold it in at the last moment. Mixed into the dough the night before, it dissolves, and dissolved pearl sugar is just sugar."},{"text":"Leave the shaped pieces on the counter until they lose their chill and start to puff.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Heat the waffle iron to medium and brush it with the neutral oil.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake one piece at a time until the sugar that has run out to the edges has caramelised to a deep amber.","duration_minutes":4,"temperature":null,"tip":"Wipe the iron between waffles. Burnt escaped caramel from the last one is the fastest way to make the next one bitter."},{"text":"Lift each waffle onto a wire rack rather than a plate, so the caramel sets hard instead of steaming itself soft.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.5,"variant_titles":["{title} with Dark Chocolate","Brown Butter {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- brazilian-coxinha.json
insert into sim.dish (slug, doc) values (
  $sd$brazilian-coxinha$sd$,
  $sd${"title":"Coxinha","description":"Shredded chicken bound in a soft cheese filling, wrapped in a cooked dough and fried into a teardrop. Makes about eighteen, which is fewer than you think once people find them.\n\nThe dough is cooked in the pan like choux and shaped while it is still warm. Cold dough cracks along every fold and the filling escapes in the fryer.","cuisine":"Brazilian","category":"Appetizer","difficulty":"hard","prep_minutes":50,"cook_minutes":40,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Filling","ingredients":[{"quantity":500,"unit":"g","name":"chicken thighs","note":"boneless","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced fine","is_optional":false,"food_id":null},{"quantity":2,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"tomato","note":"deseeded and diced","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"cream cheese","note":"full fat, at room temperature","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"parsley","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]},{"name":"Dough","ingredients":[{"quantity":500,"unit":"ml","name":"chicken broth","note":"reserved from poaching","is_optional":false,"food_id":null},{"quantity":250,"unit":"ml","name":"milk","note":null,"is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"g","name":"plain flour","note":null,"is_optional":false,"food_id":null}]},{"name":"Coating","ingredients":[{"quantity":2,"unit":null,"name":"eggs","note":"beaten","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"breadcrumbs","note":"fine and dry","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"neutral oil","note":"for frying","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Filling","steps":[{"text":"Poach the chicken thighs in lightly seasoned water until they pull apart easily, then lift them out and keep every drop of the broth.","duration_minutes":25,"temperature":null,"tip":"The poaching liquid becomes the dough. Throw it away and you are making a plain flour paste instead of a coxinha."},{"text":"Soften the onion and garlic in a little oil, add the diced tomato, and cook it to a thick base with no free liquid left.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Shred the chicken, fold it into the base with the cream cheese and parsley, and season with the salt and black pepper. Spread it out to cool completely.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Dough","steps":[{"text":"Bring the reserved chicken broth, milk, and butter to a rolling boil.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Tip in all the plain flour at once and beat it over the heat until it comes together in one lump that leaves the sides of the pan clean.","duration_minutes":5,"temperature":null,"tip":"It will look wrong for about ninety seconds. Keep beating; it turns from paste to dough all at once."},{"text":"Turn the dough onto a board and knead it while it is still hot until it is smooth and springs back.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Cover it and rest it only until it is cool enough to hold.","duration_minutes":20,"temperature":null,"tip":null}]},{"name":"Shaping and frying","steps":[{"text":"Flatten a walnut of dough in your palm, spoon filling into the middle, and close it into a teardrop with a point drawn out at the top.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Roll each one through the beaten eggs and then press it into the breadcrumbs.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Chill the shaped coxinhas so the dough firms up before it meets the fat.","duration_minutes":60,"temperature":null,"tip":null},{"text":"Fry them in the neutral oil a few at a time, turning once, until deep golden all over, and drain them point-up.","duration_minutes":7,"temperature":"170°C / 340°F","tip":"Crowding the pan drops the heat and the dough drinks oil. Six at a time is faster than twelve."}]}],"weight":0.8,"variant_titles":["{title} with Extra Cheese","Baked {title}","Mini {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- british-lemon-posset.json
insert into sim.dish (slug, doc) values (
  $sd$british-lemon-posset$sd$,
  $sd${"title":"Lemon Posset","description":"Three ingredients, one pan, and no setting agent — the acid in the lemon does all of it. Sets to something between a custard and a curd in four hours.\n\nThe ratio matters more than the technique. Too little lemon and it never sets; too much and it splits.","cuisine":"British","category":"Dessert","difficulty":"easy","prep_minutes":10,"cook_minutes":8,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":600,"unit":"ml","name":"heavy cream","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"lemons","note":"zest of two, juice of all three","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"raspberries","note":"to serve","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the heavy cream, sugar, and lemon zest to a boil, stirring until the sugar has dissolved.","duration_minutes":5,"temperature":null,"tip":"Use a bigger pan than seems necessary — cream climbs fast once it goes."},{"text":"Boil steadily for three minutes, watching it does not go over.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Take off the heat, stir in the lemon juice, and leave it to thicken slightly.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Strain out the zest and pour into four glasses.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Chill until set.","duration_minutes":240,"temperature":null,"tip":null},{"text":"Serve with raspberries.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["{title} with Shortbread","Blood Orange {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- bulgarian-shopska-salad.json
insert into sim.dish (slug, doc) values (
  $sd$bulgarian-shopska-salad$sd$,
  $sd${"title":"Shopska Salad","description":"Tomato, cucumber, and pepper under a thick white drift of grated sirene. Nothing is cooked and nothing is complicated, which means the tomatoes have to be worth eating on their own.\n\nSirene is a firm white brine cheese. Feta is the usual substitute, but rinse it first — feta is saltier and this salad has nowhere to hide it.","cuisine":"Bulgarian","category":"Salad","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":null,"name":"tomatoes","note":"ripe, cut into 2 cm chunks","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"cucumbers","note":"peeled in stripes, diced","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"green pepper","note":"seeded and diced","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"sliced into thin half moons","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"sirene","note":"or a mild feta","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"sunflower oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Slice the onion into thin half moons and leave them sitting in cold water while you cut everything else.","duration_minutes":10,"temperature":null,"tip":"Ten minutes in water takes the burn out of a raw onion without turning it limp. Longer and it starts tasting of nothing."},{"text":"Cut the tomatoes into rough chunks and the cucumbers into pieces of roughly the same size.","duration_minutes":null,"temperature":null,"tip":"Matching the sizes is most of what makes this bowl look like the picture. It is also the only knife work in it."},{"text":"Dice the green pepper and drain the onion thoroughly, shaking off every drop.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss it all together with the sunflower oil, red wine vinegar, salt, and most of the parsley.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Grate the sirene over the top in a thick even blanket and finish with the last of the parsley.","duration_minutes":null,"temperature":null,"tip":"The cheese goes on top and stays on top. Tossed through, it dissolves into the dressing and the whole bowl goes cloudy."}]}],"weight":1.8,"variant_titles":["{title} with Roasted Peppers","Summer {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- burmese-coconut-chicken-noodles.json
insert into sim.dish (slug, doc) values (
  $sd$burmese-coconut-chicken-noodles$sd$,
  $sd${"title":"Ohn No Khao Swè","description":"Chicken in a coconut broth thickened with toasted chickpea flour, poured over egg noodles. Everything else goes on at the table, which is half the pleasure of it.\n\nThe chickpea flour is what separates this from a coconut curry with noodles in it. It gives the broth a nutty body that fat alone never does, and it is the reason the soup clings to the noodles instead of sliding off them.","cuisine":"Burmese","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":40,"servings":4,"attribution":null,"ingredient_groups":[{"name":"For the soup","ingredients":[{"quantity":500,"unit":"g","name":"chicken thighs","note":"boneless, cut into bite-sized pieces","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"peanut oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"roughly cut","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"cm","name":"ginger","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"paprika","note":"for colour more than heat","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"chickpea flour","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"ml","name":"coconut milk","note":"full fat","is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"chicken stock","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"g","name":"egg noodles","note":null,"is_optional":false,"food_id":null}]},{"name":"For the table","ingredients":[{"quantity":2,"unit":null,"name":"eggs","note":"hard boiled and quartered","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"red onion","note":"sliced paper thin","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"fried shallots","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lime","note":"cut into wedges","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"coriander","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"chilli flakes","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"The soup","steps":[{"text":"Blend the onions, garlic and ginger to a smooth paste with a splash of water.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the paste in the peanut oil over a medium heat until it has darkened by two shades and no longer smells raw.","duration_minutes":12,"temperature":"medium","tip":"This is the longest twelve minutes in the recipe and the one everybody cuts short. Wait until the oil separates out at the edges of the pan."},{"text":"Stir in the turmeric and paprika, then add the chicken thighs and turn them until every piece is coated and sealed.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Whisk the chickpea flour into the cold chicken stock until there is not a lump left, then pour it into the pan along with the coconut milk and the fish sauce.","duration_minutes":null,"temperature":null,"tip":"Slurry first, every time. Chickpea flour dropped into hot liquid sets into pellets you will be fishing out all evening."},{"text":"Simmer, stirring now and then, until the soup thickens enough to coat the back of a spoon.","duration_minutes":15,"temperature":"low","tip":null}]},{"name":"The bowl","steps":[{"text":"Boil the egg noodles, drain them hard, and divide them between deep bowls.","duration_minutes":4,"temperature":null,"tip":"Drain them properly. Water left clinging to the noodles thins the soup right where you poured it."},{"text":"Ladle the soup over the noodles and let everyone build their own bowl with the eggs, red onion, fried shallots, lime, coriander and chilli flakes.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Tofu","Quick {title}","{title}, Extra Coconut"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- cambodian-yellow-kroeung.json
insert into sim.dish (slug, doc) values (
  $sd$cambodian-yellow-kroeung$sd$,
  $sd${"title":"Yellow Kroeung","description":"The lemongrass and turmeric paste that sits under most Khmer cooking. Pounded, never blended, and made in a batch — this yields about a cupful, enough to season two curries.\n\nA food processor will give you something yellow and fragrant, and it will not be kroeung. Blades cut the lemongrass fibre into short splinters; a pestle crushes it open and releases the oil. If you must use a machine, pound the lemongrass by hand first and blitz the rest.","cuisine":"Cambodian","category":"Sauce","difficulty":"medium","prep_minutes":25,"cook_minutes":0,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":6,"unit":null,"name":"lemongrass stalks","note":"outer layers stripped, pale core only, sliced as thinly as possible","is_optional":false,"food_id":null},{"quantity":8,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"shallots","note":"quartered","is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"galangal","note":"peeled and sliced across the grain","is_optional":false,"food_id":null},{"quantity":20,"unit":"g","name":"turmeric","note":"the fresh root, peeled; 2 tsp of the dried powder at a push","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"makrut lime leaves","note":"centre ribs torn out","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"dried red chillies","note":"soaked in warm water and drained","is_optional":true,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"shrimp paste","note":"toasted in foil until it smells of the sea","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Slice the lemongrass stalks as thinly as your knife allows, working only with the pale core.","duration_minutes":null,"temperature":null,"tip":"This is the difference between a smooth paste and one full of splinters. If a slice bends instead of snapping, it belongs in the stock pot."},{"text":"Pound the lemongrass with the salt on its own until it collapses into a wet green pulp.","duration_minutes":8,"temperature":null,"tip":"The salt is the abrasive. Pound the toughest thing first, with nothing soft to cushion it, and the mortar does the work instead of your shoulder."},{"text":"Add the makrut lime leaves and the galangal and keep going until neither is recognisable in the pulp.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Work in the turmeric, then the shallots and the garlic, one at a time and never two together.","duration_minutes":7,"temperature":null,"tip":"The order matters. Anything wet added early turns the mortar into a bowl of soup and the fibres never break down after that."},{"text":"Pound in the dried red chillies and the shrimp paste last if you are using them, then rub a little of the paste between your fingers to check it is smooth.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pack the kroeung into a jar, press the surface flat, and film it with a thin layer of oil.","duration_minutes":null,"temperature":null,"tip":"A week in the fridge, or freeze it in tablespoon blobs. It darkens as it sits, which is oxidation and not spoilage."}]}],"weight":0.9,"variant_titles":["{title} for Fish","Blender {title}","Mild {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- canadian-peameal-bacon-sandwich.json
insert into sim.dish (slug, doc) values (
  $sd$canadian-peameal-bacon-sandwich$sd$,
  $sd${"title":"Peameal Bacon Sandwich","description":"Pork loin cured in brine for a day, rolled in cornmeal, and griddled in thick slices. Toronto's market breakfast, on a soft kaiser roll with a hard smear of mustard.\n\nThis is a wet cure and not a smoke. The meat stays pale the whole way through and the cornmeal crust is the only colour on it until it hits the pan.","cuisine":"Canadian","category":"Breakfast","difficulty":"medium","prep_minutes":25,"cook_minutes":12,"servings":6,"attribution":null,"ingredient_groups":[{"name":"The cure","ingredients":[{"quantity":1,"unit":"kg","name":"pork loin","note":"trimmed of all but a thin fat cap","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":80,"unit":"g","name":"fine salt","note":null,"is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"bay leaves","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"black peppercorns","note":"cracked","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"curing salt","note":"pink salt no. 1, for colour only","is_optional":true,"food_id":null}]},{"name":"The sandwich","ingredients":[{"quantity":150,"unit":"g","name":"cornmeal","note":"medium grind","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"kaiser rolls","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"grainy mustard","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"maple syrup","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"The cure","steps":[{"text":"Dissolve the fine salt and sugar in the water with the bay leaves and cracked black peppercorns, stir in the curing salt if you are using it, and chill the brine until it is properly cold.","duration_minutes":60,"temperature":null,"tip":"Warm brine on raw meat is the one genuinely unsafe thing you can do here. Cold all the way, no exceptions."},{"text":"Submerge the pork loin in the brine and weigh it down with a plate so no part of it floats clear.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Refrigerate it for a full day, turning it once halfway through.","duration_minutes":1440,"temperature":null,"tip":null},{"text":"Rinse the loin under cold water, pat it completely dry, and roll it hard in the cornmeal until it is coated on every face.","duration_minutes":null,"temperature":null,"tip":"Dry meat takes cornmeal; damp meat takes a paste that slides off in the pan."}]},{"name":"The sandwich","steps":[{"text":"Cut the cured loin across into slices a good centimetre thick.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Griddle the slices in the butter over a medium heat, about three minutes a side, until the cornmeal has toasted and the meat is just cooked through.","duration_minutes":12,"temperature":"medium","tip":null},{"text":"Brush them with the maple syrup for the last thirty seconds if you want the sweet edge on it.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Split and toast the kaiser rolls, spread them with the grainy mustard, and pile in three slices each while everything is still hot.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["{title} with Maple","{title}, Market Style"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- chinese-ginger-congee.json
insert into sim.dish (slug, doc) values (
  $sd$chinese-ginger-congee$sd$,
  $sd${"title":"Ginger Congee","description":"Rice cooked far past the point most recipes stop, until the grains dissolve into something between soup and porridge. Plain on purpose — the toppings do the talking.\n\nFreezing the rinsed rice overnight breaks the grains and cuts the cooking time by about a third.","cuisine":"Chinese","category":"Breakfast","difficulty":"easy","prep_minutes":5,"cook_minutes":90,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":150,"unit":"g","name":"jasmine rice","note":"rinsed until the water runs clear","is_optional":false,"food_id":null},{"quantity":2,"unit":"L","name":"chicken stock","note":"or water for a plainer bowl","is_optional":false,"food_id":null},{"quantity":1,"unit":"large piece","name":"ginger","note":"half sliced, half julienned","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to serve","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"soy sauce","note":"to serve","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sesame oil","note":"to serve","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":"soft boiled, to serve","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the jasmine rice, chicken stock, sliced ginger, and salt to a boil in a large pot.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Drop to the lowest possible heat and cook uncovered, stirring every fifteen minutes or so.","duration_minutes":80,"temperature":"low","tip":"Stir along the bottom each time — congee catches and scorches without warning."},{"text":"Stop when the grains have broken down and the congee coats the back of a spoon. Loosen with hot water if it has gone too far.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve topped with the julienned ginger, spring onions, soy sauce, sesame oil, and a soft boiled egg.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Century Egg","Sick-Day {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- colombian-arepas.json
insert into sim.dish (slug, doc) values (
  $sd$colombian-arepas$sd$,
  $sd${"title":"Cheese Arepas","description":"Corn cakes made from precooked masarepa, griddled until they blister and split open with steam. Four ingredients, and the dough tells you when it is right.\n\nMasarepa is not the same as masa harina and not the same as cornmeal — neither substitute works.","cuisine":"Colombian","category":"Side","difficulty":"easy","prep_minutes":15,"cook_minutes":20,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":250,"unit":"g","name":"masarepa","note":"precooked white corn flour","is_optional":false,"food_id":null},{"quantity":400,"unit":"ml","name":"warm water","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"queso fresco","note":"crumbled; mozzarella works","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"butter","note":"for the griddle","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Stir the salt into the warm water, then rain in the masarepa, mixing with your hand.","duration_minutes":null,"temperature":null,"tip":"Flour into water, not the other way round — it hydrates evenly and you get no dry pockets."},{"text":"Knead in the queso fresco and let the dough rest so the corn finishes absorbing.","duration_minutes":10,"temperature":null,"tip":"The dough should feel like soft clay. If it cracks at the edge when you flatten it, wet your hands and knead again."},{"text":"Shape into eight discs about a centimetre thick, smoothing the edges between wet palms.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Griddle in butter over a medium heat until a crust forms and they sound hollow, turning once.","duration_minutes":20,"temperature":"medium","tip":"A finished arepa puffs slightly and hisses. Do not press it down."}]}],"weight":1.3,"variant_titles":["{title} with Butter","Stuffed {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- croatian-black-risotto.json
insert into sim.dish (slug, doc) values (
  $sd$croatian-black-risotto$sd$,
  $sd${"title":"Dalmatian Black Risotto","description":"Cuttlefish risotto stained through with its own ink. Everything about it is timing: the seafood and the rice have to finish in the same minute, and the ink goes in last so the colour is even.\n\nAsk the fishmonger to clean the cuttlefish and to keep the ink sacs for you. Sold separately, ink comes in 4 g sachets and two is right for this quantity.","cuisine":"Croatian","category":"Main","difficulty":"hard","prep_minutes":30,"cook_minutes":40,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":600,"unit":"g","name":"cuttlefish","note":"cleaned","is_optional":false,"food_id":null},{"quantity":320,"unit":"g","name":"arborio rice","note":null,"is_optional":false,"food_id":null},{"quantity":8,"unit":"g","name":"squid ink","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"finely diced","is_optional":false,"food_id":null},{"quantity":3,"unit":"cloves","name":"garlic","note":"finely chopped","is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"white wine","note":"dry","is_optional":false,"food_id":null},{"quantity":1.2,"unit":"L","name":"fish stock","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":"cold, cubed","is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"Parmesan","note":"finely grated","is_optional":true,"food_id":null},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Cut the cleaned cuttlefish into strips about the width of a pencil.","duration_minutes":null,"temperature":null,"tip":"Anything thicker cooks on a different clock than the rice and stays rubbery in a finished pan."},{"text":"Bring the fish stock to a bare simmer in a second pan and keep it there for the whole cook.","duration_minutes":null,"temperature":null,"tip":"Cold stock stalls the pan every time you ladle. The rice stops releasing starch and never comes back."},{"text":"Sweat the onion and garlic in the olive oil until translucent, then add the cuttlefish and cook until it gives up its liquid and that liquid disappears again.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Stir in the arborio rice and toast it until the grains look glassy at the edges and chalky in the middle.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Pour in the white wine and let it cook away completely before any stock goes near the pan.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Add the hot stock a ladle at a time, stirring, waiting each time until the pan is almost dry before the next.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Whisk the squid ink into the final ladle of stock and stir that through the rice.","duration_minutes":null,"temperature":null,"tip":"Ink dropped straight into the pan streaks and stays streaked. Diluted first, it colours the whole thing in one turn of the spoon."},{"text":"Off the heat, beat in the cold butter and the Parmesan hard enough to make the risotto loose, season with salt and black pepper, and finish with parsley.","duration_minutes":null,"temperature":null,"tip":"It should spread slowly on a tilted plate. If it holds a mound, it is too tight — another splash of stock."}]}],"weight":0.5,"variant_titles":["{title} with Squid","{title} for Two"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- cuban-croquetas-de-jamon.json
insert into sim.dish (slug, doc) values (
  $sd$cuban-croquetas-de-jamon$sd$,
  $sd${"title":"Croquetas de Jamón","description":"A stiff béchamel worked through with finely chopped ham, chilled until it slices, then breaded and fried into short cylinders. Makes about twenty.\n\nThe paste must be cold and firm before you shape anything. No amount of extra flour will make a warm béchamel hold a cylinder.","cuisine":"Cuban","category":"Snack","difficulty":"medium","prep_minutes":30,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"The paste","ingredients":[{"quantity":60,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"grated on the coarse side","is_optional":false,"food_id":null},{"quantity":90,"unit":"g","name":"plain flour","note":null,"is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"milk","note":"warmed","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"serrano ham","note":"chopped as fine as you have patience for","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"nutmeg","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"white pepper","note":null,"is_optional":false,"food_id":null}]},{"name":"Coating and frying","ingredients":[{"quantity":60,"unit":"g","name":"plain flour","note":"for dusting","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"eggs","note":"beaten","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"breadcrumbs","note":"fine and dry","is_optional":false,"food_id":null},{"quantity":750,"unit":"ml","name":"neutral oil","note":"for frying","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The paste","steps":[{"text":"Sweat the onion in the butter over a low heat until it is soft and has taken no colour at all.","duration_minutes":6,"temperature":null,"tip":null},{"text":"Stir in the plain flour and cook the raw taste out of it, then add the warm milk a splash at a time, beating it smooth before the next one goes in.","duration_minutes":12,"temperature":null,"tip":"Add the milk faster than this and you will spend the rest of the evening chasing lumps around the pan."},{"text":"Beat until the paste comes away from the sides in one mass, then fold through the serrano ham and season with the nutmeg, salt, and white pepper.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Spread it thin in a tray, press cling film onto the surface, and chill it until it is firm enough to cut.","duration_minutes":180,"temperature":null,"tip":null}]},{"name":"Shaping and frying","steps":[{"text":"Cut the cold paste into strips and roll each strip into a short cylinder between floured palms.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pass each croqueta through the plain flour, then the beaten eggs, then the breadcrumbs, pressing the crumbs on firmly.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Chill the breaded croquetas again while the neutral oil comes up to temperature.","duration_minutes":20,"temperature":null,"tip":"The second chill is what stops them splitting. A croqueta that bursts in the pan was warm going in."},{"text":"Fry them a few at a time until they are deep gold, then drain them standing on end so the bottoms stay crisp.","duration_minutes":7,"temperature":"180°C / 355°F","tip":null}]}],"weight":0.9,"variant_titles":["{title} with Chicken","{title}, Party Size"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- czech-kulajda.json
insert into sim.dish (slug, doc) values (
  $sd$czech-kulajda$sd$,
  $sd${"title":"Kulajda","description":"A soured cream soup of potato, mushroom, and a great deal of dill, with a poached egg dropped into each bowl. It should taste sour first and sweet a moment later — that balance is the whole dish.\n\nCut the dill stems in with the fronds. They carry more of the flavour and they soften completely in the pot.","cuisine":"Czech","category":"Soup","difficulty":"medium","prep_minutes":20,"cook_minutes":35,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":300,"unit":"g","name":"potatoes","note":"cut into 1 cm cubes","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"mushrooms","note":"sliced; wild ones if you have them","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"vegetable stock","note":null,"is_optional":false,"food_id":null},{"quantity":200,"unit":"ml","name":"sour cream","note":"full fat","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"plain flour","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"bunch","name":"dill","note":"chopped, stems included","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"white wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":"as fresh as you can get","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"caraway seeds","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"bay leaf","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Simmer the potatoes with the bay leaf, caraway seeds, and salt in the vegetable stock until a cube is just short of tender.","duration_minutes":12,"temperature":null,"tip":null},{"text":"Add the sliced mushrooms and cook until they darken and sink.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Whisk the plain flour into the sour cream until there is not a lump left, then slacken it with a ladleful of the hot broth.","duration_minutes":null,"temperature":null,"tip":"Tempering is the whole trick. Cold cream straight into a simmering pot splits into curds and no amount of whisking gathers it back."},{"text":"Stir the slackened cream into the pot and hold it just below a simmer — it must not boil again.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Fish out the bay leaf, then season with the white wine vinegar, sugar, and black pepper, adding the vinegar a spoon at a time.","duration_minutes":null,"temperature":null,"tip":"Aim for sour on the front of the tongue and sweet behind it. If it lands flat, it is almost always short of vinegar rather than salt."},{"text":"Poach the eggs in a separate pan of barely trembling water.","duration_minutes":4,"temperature":null,"tip":null},{"text":"Stir most of the dill into the pot, ladle out, slide an egg into each bowl, and scatter the rest of the dill over.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["Forager's {title}","{title} with a Soft-Boiled Egg"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- dutch-uitsmijter.json
insert into sim.dish (slug, doc) values (
  $sd$dutch-uitsmijter$sd$,
  $sd${"title":"Uitsmijter","description":"Fried eggs over ham and melting cheese on buttered toast, eaten with a knife and fork. Ten minutes start to finish, and the only decision in it is how loose you want the yolks.\n\nTwo slices and two eggs per person is the standard portion. It is named for the bouncer who throws you out at closing time, which tells you roughly when it is meant to be eaten.","cuisine":"Dutch","category":"Breakfast","difficulty":"easy","prep_minutes":5,"cook_minutes":8,"servings":2,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":"slices","name":"sourdough bread","note":"cut thick","is_optional":false,"food_id":null},{"quantity":4,"unit":"slices","name":"cooked ham","note":null,"is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"Gouda","note":"young, sliced thin","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.25,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"chives","note":"snipped","is_optional":true,"food_id":null},{"quantity":2,"unit":"tsp","name":"mustard","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Spread half the butter over both faces of the sourdough bread and lay the slices in a wide cold pan.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Turn the heat to medium, toast one side to a light brown, and flip.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Lay the cooked ham over the toasted face and the Gouda on top of the ham, then cover the pan so the cheese slumps.","duration_minutes":2,"temperature":null,"tip":"Cheese directly on the toast leaks fat into the crumb. Ham underneath keeps the base crisp and the cheese where you put it."},{"text":"Fry the eggs in the rest of the butter in a second pan, spooning the hot fat over the whites until they set and the yolks are still loose.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Slide two eggs onto each slice, season with salt and black pepper, and scatter the chives over.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Put the mustard on the side and eat it straight away, while the yolk still runs.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.7,"variant_titles":["{title} with Roast Beef","{title} on Rye"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- egyptian-koshari.json
insert into sim.dish (slug, doc) values (
  $sd$egyptian-koshari$sd$,
  $sd${"title":"Koshari","description":"Rice, lentils, and pasta layered under a sharp tomato sauce, cumin vinegar, and a heap of fried onions. Egypt's national dish and the best argument for carbohydrate on carbohydrate.\n\nEvery component can be made ahead. Assemble only at the table — the fried onions go soft within minutes of meeting the sauce.","cuisine":"Egyptian","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":60,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Base","ingredients":[{"quantity":200,"unit":"g","name":"brown lentils","note":"rinsed","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"rice","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"small pasta","note":"elbows or ditalini","is_optional":false,"food_id":null},{"quantity":400,"unit":"g","name":"chickpeas","note":"cooked and drained","is_optional":false,"food_id":null}]},{"name":"Tomato sauce","ingredients":[{"quantity":700,"unit":"g","name":"tomato passata","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"white vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cumin","note":"ground","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"chilli flakes","note":null,"is_optional":false,"food_id":null}]},{"name":"Crispy onions","ingredients":[{"quantity":3,"unit":null,"name":"onions","note":"sliced very thin","is_optional":false,"food_id":null},{"quantity":250,"unit":"ml","name":"neutral oil","note":"for frying","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Crispy onions","steps":[{"text":"Fry the sliced onions in the neutral oil over a steady medium heat until deep brown and crisp, then drain on paper.","duration_minutes":25,"temperature":null,"tip":"They go from brown to burnt fast at the end. Pull them a shade early — they darken on the paper."},{"text":"Keep a few spoonfuls of the onion oil back for the lentils.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Base","steps":[{"text":"Simmer the brown lentils in plenty of water until tender but still holding shape, then drain.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Cook the rice in the reserved onion oil and water until done, and boil the pasta separately.","duration_minutes":18,"temperature":null,"tip":null}]},{"name":"Sauce and assembly","steps":[{"text":"Fry the garlic briefly, add the tomato passata, cumin, chilli flakes, and white vinegar, and simmer until thickened.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Layer rice, lentils, pasta, and chickpeas in a wide dish.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pour the hot sauce over and finish with a generous pile of crispy onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Street-Style {title}","{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- ethiopian-misir-wot.json
insert into sim.dish (slug, doc) values (
  $sd$ethiopian-misir-wot$sd$,
  $sd${"title":"Misir Wot","description":"Red lentils cooked down with berbere and a large quantity of onion, which is dry-cooked first without any fat at all. Thick enough to eat with bread rather than a spoon.\n\nBerbere varies enormously in heat between brands. Start with half and build.","cuisine":"Ethiopian","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":55,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"red onions","note":"diced very fine","is_optional":false,"food_id":null},{"quantity":250,"unit":"g","name":"red lentils","note":"rinsed","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"berbere","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"niter kibbeh","note":"spiced clarified butter; or plain ghee","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"water","note":"hot","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Cook the red onions in a dry pan, with no oil, stirring often until they collapse and release their moisture.","duration_minutes":15,"temperature":"medium-low","tip":"This sounds wrong and is the defining step. The onions steam in their own liquid and go sweet without frying."},{"text":"Add the niter kibbeh, garlic, and ginger and cook until fragrant.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Stir in the berbere and tomato paste and cook them out so the spice loses its raw edge.","duration_minutes":4,"temperature":null,"tip":null},{"text":"Add the red lentils and the hot water, and simmer, stirring now and then.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Season with the salt and cook until it is thick enough to hold the mark of a spoon.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Injera","Mild {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- filipino-garlic-fried-rice.json
insert into sim.dish (slug, doc) values (
  $sd$filipino-garlic-fried-rice$sd$,
  $sd${"title":"Garlic Fried Rice","description":"Sinangag. Day-old rice fried in garlic oil with a heavy hand of fried garlic folded back through at the end. A side dish that quietly outshines what it is served with.\n\nFreshly cooked rice will not work — it steams and clumps. Cold rice from yesterday is the requirement, not a shortcut.","cuisine":"Filipino","category":"Side","difficulty":"easy","prep_minutes":10,"cook_minutes":15,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":"cups","name":"cooked rice","note":"cold, from the day before, broken up by hand","is_optional":false,"food_id":null},{"quantity":12,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"neutral oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":"fried, to serve","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Fry the minced garlic in the neutral oil over a medium-low heat until pale gold, then lift half of it out onto paper.","duration_minutes":5,"temperature":"medium-low","tip":"Pull it while it is lighter than you want — it keeps browning on the paper. Burnt garlic is bitter and unfixable."},{"text":"Turn the heat up, add the cold cooked rice to the garlic oil left in the pan, and press it into an even layer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave it alone so the underside crisps, then turn and repeat.","duration_minutes":8,"temperature":null,"tip":"Constant stirring gives you warm rice. Stillness gives you texture."},{"text":"Season with the salt, fold through the reserved crisp garlic and the spring onions, and serve with a fried egg.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.4,"variant_titles":["{title} with Longganisa","Everyday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- french-coq-au-vin.json
insert into sim.dish (slug, doc) values (
  $sd$french-coq-au-vin$sd$,
  $sd${"title":"Coq au Vin","description":"Chicken braised in red wine with bacon, mushrooms, and small onions. The garnish is cooked separately and added at the end so it does not turn grey in the pot.\n\nA whole bottle goes in. Use one you would drink, but not one you would miss.","cuisine":"French","category":"Main","difficulty":"hard","prep_minutes":40,"cook_minutes":90,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Braise","ingredients":[{"quantity":1.6,"unit":"kg","name":"chicken","note":"jointed into eight pieces","is_optional":false,"food_id":null},{"quantity":750,"unit":"ml","name":"red wine","note":"a full bottle","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"bacon lardons","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"bouquet garni","note":"thyme, bay, parsley stalks tied together","is_optional":false,"food_id":null},{"quantity":300,"unit":"ml","name":"chicken stock","note":null,"is_optional":false,"food_id":null}]},{"name":"Garnish","ingredients":[{"quantity":250,"unit":"g","name":"button mushrooms","note":"left whole if small","is_optional":false,"food_id":null},{"quantity":250,"unit":"g","name":"pearl onions","note":"peeled","is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Braise","steps":[{"text":"Render the bacon lardons in a heavy pot until crisp, then lift them out.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Brown the chicken hard in the bacon fat, in batches, and set aside.","duration_minutes":15,"temperature":null,"tip":"Crowding the pan steams the skin. Batches are slower and not optional."},{"text":"Stir the flour and tomato paste into the fat with the crushed garlic and cook out the raw taste.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Pour in the red wine, scraping the base, and reduce by about a third.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Return the chicken and bacon, add the chicken stock and bouquet garni, and simmer covered.","duration_minutes":60,"temperature":"low","tip":null}]},{"name":"Garnish and finish","steps":[{"text":"Brown the pearl onions and button mushrooms separately in the butter until well coloured.","duration_minutes":12,"temperature":null,"tip":"Cooking these in the braise turns them the colour of the wine. Separate is the whole point."},{"text":"Add the garnish to the pot for the last few minutes, discard the bouquet garni, and check the seasoning.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Finish with chopped parsley.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["{title} Blanc","Sunday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- georgian-khachapuri.json
insert into sim.dish (slug, doc) values (
  $sd$georgian-khachapuri$sd$,
  $sd${"title":"Adjaruli Khachapuri","description":"A boat of enriched dough filled with salty cheese, finished with an egg yolk and butter stirred through at the table while everything is still molten.\n\nYou tear the pointed ends off and use them to stir the yolk into the cheese. That is the correct way to eat it and it is not optional.","cuisine":"Georgian","category":"Main","difficulty":"medium","prep_minutes":30,"cook_minutes":18,"servings":2,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":300,"unit":"g","name":"bread flour","note":null,"is_optional":false,"food_id":null},{"quantity":175,"unit":"ml","name":"milk","note":"warm","is_optional":false,"food_id":null},{"quantity":7,"unit":"g","name":"instant yeast","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null}]},{"name":"Filling","ingredients":[{"quantity":200,"unit":"g","name":"sulguni","note":"or half mozzarella, half feta","is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"feta","note":"crumbled","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"egg yolks","note":null,"is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"butter","note":"cubed","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Mix the bread flour, instant yeast, sugar, and salt, then work in the warm milk and olive oil and knead until smooth.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Prove until doubled.","duration_minutes":90,"temperature":null,"tip":null}]},{"name":"Shaping and baking","steps":[{"text":"Divide in two, roll each piece into an oval, and roll the long sides inward to make thick ropes.","duration_minutes":null,"temperature":null,"tip":"Pinch the two ends together hard. A boat that opens in the oven loses all its cheese."},{"text":"Mix the sulguni and feta and heap it into each boat.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake until the crust is deep gold and the cheese is bubbling.","duration_minutes":15,"temperature":"450°F","tip":null},{"text":"Pull the tray out, drop an egg yolk and some butter into each pool of cheese, and return briefly so the yolk warms without setting.","duration_minutes":2,"temperature":null,"tip":"The yolk should still be liquid when it reaches the table."}]}],"weight":0.9,"variant_titles":["{title} for One","Imeruli {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- german-dutch-baby.json
insert into sim.dish (slug, doc) values (
  $sd$german-dutch-baby$sd$,
  $sd${"title":"Dutch Baby Pancake","description":"A single pancake that climbs the sides of a hot skillet in the oven and collapses the moment it comes out. Five minutes of work, and the batter does the rest.\n\nRoom-temperature eggs and milk are the difference between a dramatic rise and a flat disc.","cuisine":"German","category":"Breakfast","difficulty":"easy","prep_minutes":10,"cook_minutes":20,"servings":2,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"eggs","note":"room temperature","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"milk","note":"room temperature","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":0.25,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lemon","note":"to serve","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"powdered sugar","note":"to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Put a cast iron skillet in the oven and heat it thoroughly.","duration_minutes":15,"temperature":"425°F","tip":"The pan must be properly hot before the batter hits it. This is the whole trick."},{"text":"Blend the eggs, milk, flour, sugar, and salt until completely smooth and slightly frothy.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Let the batter stand while the pan finishes heating.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Drop the butter into the hot skillet, swirl it up the sides as it melts, then pour the batter straight in.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bake without opening the door until puffed and deeply browned at the edges.","duration_minutes":20,"temperature":"425°F","tip":null},{"text":"Serve straight from the pan with a squeeze of lemon and a dusting of powdered sugar.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Savoury {title}","{title} with Berries"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- ghanaian-sobolo.json
insert into sim.dish (slug, doc) values (
  $sd$ghanaian-sobolo$sd$,
  $sd${"title":"Sobolo","description":"Dried hibiscus steeped with ginger, spice, and pineapple skin, then left overnight and sweetened cold. Deep red, properly tart, and served in a jug with far too much ice.\n\nSweeten it cold, never hot. Sugar reads weaker in a hot pan and you will overshoot every single time.","cuisine":"Ghanaian","category":"Drink","difficulty":"easy","prep_minutes":10,"cook_minutes":15,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":100,"unit":"g","name":"dried hibiscus","note":"sorrel calyces","is_optional":false,"food_id":null},{"quantity":2,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":80,"unit":"g","name":"ginger","note":"peeled and sliced thin","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"pineapple","note":"skin and core only, scrubbed","is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"cloves","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"cinnamon stick","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"sugar","note":"adjust to the fruit","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"limes","note":"juiced","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Rinse the dried hibiscus in cold water and pick out any stalks or grit.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Bring the water to a boil with the ginger, cinnamon stick, cloves, and the scrubbed pineapple skin.","duration_minutes":10,"temperature":null,"tip":"The pineapple skin is not a garnish. It carries most of the sweetness the drink has before any sugar goes in."},{"text":"Take the pan off the heat, tip in the hibiscus, cover it, and let it steep until the colour is opaque.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Strain into a jug and refrigerate overnight so it settles and the flavour deepens.","duration_minutes":720,"temperature":null,"tip":null},{"text":"Sweeten the cold drink with the sugar a spoonful at a time, then sharpen it with the lime juice until it makes you wince slightly.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve over more ice than seems reasonable — it is meant to dilute as you drink it.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.5,"variant_titles":["Spiced {title}","{title} with Pineapple"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- greek-lamb-souvlaki.json
insert into sim.dish (slug, doc) values (
  $sd$greek-lamb-souvlaki$sd$,
  $sd${"title":"Lamb Souvlaki with Tzatziki","description":"Lamb shoulder marinated overnight in lemon, oregano, and garlic, then grilled hard and fast. The tzatziki is drained twice so it stays thick instead of sliding off.","cuisine":"Greek","category":"Main","difficulty":"medium","prep_minutes":30,"cook_minutes":12,"servings":4,"attribution":null,"ingredient_groups":[{"name":"Lamb and marinade","ingredients":[{"quantity":800,"unit":"g","name":"lamb shoulder","note":"cut into 3cm cubes","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lemon","note":"zest and juice","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"dried oregano","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Tzatziki","ingredients":[{"quantity":300,"unit":"g","name":"Greek yogurt","note":"full fat","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"cucumber","note":"coarsely grated","is_optional":false,"food_id":null},{"quantity":1,"unit":"clove","name":"garlic","note":"grated fine","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"dill","note":"chopped","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The day before","steps":[{"text":"Toss the lamb shoulder with the olive oil, lemon zest and juice, oregano, crushed garlic, and salt.","duration_minutes":null,"temperature":null,"tip":"Salt in the marinade is doing double duty — it seasons and it keeps the meat juicy."},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null}]},{"name":"Tzatziki","steps":[{"text":"Salt the grated cucumber and leave it in a sieve, then squeeze it dry in a cloth.","duration_minutes":20,"temperature":null,"tip":"Squeeze harder than feels reasonable. Watery tzatziki starts here."},{"text":"Stir the cucumber into the Greek yogurt with the grated garlic, red wine vinegar, and dill.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Grilling","steps":[{"text":"Thread the lamb onto skewers, leaving a little space between the pieces so they colour rather than steam.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Grill over the highest heat you have, turning every couple of minutes.","duration_minutes":12,"temperature":"high","tip":null},{"text":"Rest the skewers before serving with the tzatziki.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title}, Family Style"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- hawaiian-ahi-poke.json
insert into sim.dish (slug, doc) values (
  $sd$hawaiian-ahi-poke$sd$,
  $sd${"title":"Ahi Poke","description":"Cubed raw tuna dressed with soy, sesame and sweet onion, and given a short rest in the fridge so the seasoning takes. Nothing is cooked and nothing should be.\n\nLimu and inamona are what make this taste of the islands rather than of a soy dressing. Rehydrated wakame and crushed roasted macadamia are the usual mainland stand-ins and both are honest substitutions.","cuisine":"Hawaiian","category":"Appetizer","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"sashimi-grade tuna","note":"cut into 2 cm cubes","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"soy sauce","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sesame oil","note":"toasted","is_optional":false,"food_id":null},{"quantity":0.5,"unit":null,"name":"sweet onion","note":"sliced paper thin","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"scallions","note":"cut on the diagonal","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"sesame seeds","note":"toasted","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"Hawaiian sea salt","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"limu","note":"chopped seaweed; rehydrated wakame stands in","is_optional":true,"food_id":null},{"quantity":1,"unit":"tsp","name":"inamona","note":"roasted crushed kukui nut; macadamia is the common substitute","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Pat the tuna dry and cut it into even cubes with a sharp knife, drawing the blade through rather than pressing down.","duration_minutes":null,"temperature":null,"tip":"A dull knife bruises the fish and you can see it — the cubes go cloudy exactly where they were crushed."},{"text":"Toss the tuna with the soy sauce, sesame oil and Hawaiian sea salt until every cube is glossy.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fold through the sweet onion, scallions, sesame seeds, limu and inamona with a light hand.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Chill for a quarter of an hour to let the seasoning take, then serve straight from the fridge.","duration_minutes":15,"temperature":null,"tip":"Do not leave it much longer than an hour. The soy starts curing the outside of the cubes and the texture turns firm and slightly chalky."}]}],"weight":1.2,"variant_titles":["{title} with Avocado","Spicy {title}","{title} Bowl"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- hungarian-goulash.json
insert into sim.dish (slug, doc) values (
  $sd$hungarian-goulash$sd$,
  $sd${"title":"Hungarian Beef Goulash","description":"A soup-thick stew built on collapsed onions and a lot of paprika, cooked long enough that the shin turns to gelatin. Makes a full pot and reheats better than it serves.\n\nPaprika is the ingredient, not the seasoning — buy it fresh and in quantity. A tin that has been open since last winter tastes of dust and no amount of it will fix the pot.","cuisine":"Hungarian","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":150,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1.2,"unit":"kg","name":"beef shin","note":"cut into 4 cm cubes","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"onions","note":"sliced thin","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"lard","note":"or a neutral oil","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"sweet paprika","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"hot paprika","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"caraway seeds","note":"lightly crushed","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"beef stock","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"green peppers","note":"seeded, cut into strips","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"tomatoes","note":"roughly chopped","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"potatoes","note":"peeled, cut into large cubes","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Cook the sliced onions in the lard over low heat until they lose every trace of structure and slump into a soft golden mass.","duration_minutes":30,"temperature":null,"tip":"Half an hour looks absurd for onions and it is not negotiable. This is the body of the finished stew — hurry it and you get flavoured water."},{"text":"Pull the pot off the heat entirely. Stir the sweet paprika and the hot paprika through the onions away from the flame, then set it back on the lowest burner.","duration_minutes":null,"temperature":null,"tip":"Paprika scorches at frying temperature in about ten seconds and the bitterness never cooks out."},{"text":"Add the beef shin, caraway seeds, garlic, salt, and black pepper, and turn the meat until every cube is red.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pour in enough beef stock to barely cover the meat, bring it to a lazy simmer, and cook covered until a cube gives way under a spoon.","duration_minutes":90,"temperature":null,"tip":"Barely covered, not swimming. You want to end up with a thick pot, and you cannot boil liquid off a stew without overcooking the meat."},{"text":"Add the green peppers, tomatoes, and potatoes and simmer uncovered until the potatoes are tender and the sauce has pulled together.","duration_minutes":25,"temperature":null,"tip":null},{"text":"Rest the pot off the heat before serving, then taste again — it will take more salt cold than it did hot.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["Slow Cooker {title}","{title} with Pinched Noodles"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- indian-chana-masala.json
insert into sim.dish (slug, doc) values (
  $sd$indian-chana-masala$sd$,
  $sd${"title":"Chana Masala","description":"Chickpeas in a dark onion-tomato masala finished with amchur for sourness rather than lemon. Entirely pantry-based and better on the second day.\n\nTinned chickpeas are fine. If cooking dried, save the cooking liquid — it thickens the gravy better than water.","cuisine":"Indian","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":40,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":800,"unit":"g","name":"chickpeas","note":"cooked, drained; two tins","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"diced fine","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"tomatoes","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"cumin","note":"ground","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"coriander","note":"ground","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"garam masala","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"amchur","note":"dried mango powder; or the juice of half a lemon","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"neutral oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"cilantro","note":"chopped, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Fry the onions in the neutral oil until well past golden — properly brown at the edges.","duration_minutes":15,"temperature":"medium","tip":"Most of the colour of the finished dish comes from here. Stopping at soft and translucent gives a pale, thin curry."},{"text":"Add the ginger and garlic and cook until the raw smell goes.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the cumin, coriander, and turmeric and stir for thirty seconds before the tomatoes go in.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the tomatoes and cook down until the oil separates out at the edges.","duration_minutes":12,"temperature":null,"tip":"Oil pooling around the masala is the signal it is ready. It is not a timing question."},{"text":"Stir in the chickpeas with a splash of water and simmer so they take on the gravy.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Crush a few chickpeas against the side of the pan to thicken, then finish with garam masala, amchur, and cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.6,"variant_titles":["Weeknight {title}","{title} with Spinach","Pantry {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- indonesian-beef-rendang.json
insert into sim.dish (slug, doc) values (
  $sd$indonesian-beef-rendang$sd$,
  $sd${"title":"Beef Rendang","description":"Beef simmered in coconut milk and spice paste until the liquid goes, then fried in the oil that separates out. The last twenty minutes are where it stops being a curry.\n\nStop early and you have a wet rendang, which is a real dish but a different one. Dry rendang keeps for days unrefrigerated, which is what it was for.","cuisine":"Indonesian","category":"Main","difficulty":"hard","prep_minutes":30,"cook_minutes":210,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Spice paste","ingredients":[{"quantity":10,"unit":null,"name":"shallots","note":"peeled","is_optional":false,"food_id":null},{"quantity":6,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":8,"unit":null,"name":"dried red chillies","note":"soaked in hot water","is_optional":false,"food_id":null},{"quantity":4,"unit":"cm","name":"galangal","note":"sliced","is_optional":false,"food_id":null},{"quantity":3,"unit":"cm","name":"ginger","note":"sliced","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"coriander","note":"ground","is_optional":false,"food_id":null}]},{"name":"Braise","ingredients":[{"quantity":1.2,"unit":"kg","name":"beef chuck","note":"cut into large cubes","is_optional":false,"food_id":null},{"quantity":800,"unit":"ml","name":"coconut milk","note":"full fat","is_optional":false,"food_id":null},{"quantity":3,"unit":"stalks","name":"lemongrass","note":"bruised","is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"kaffir lime leaves","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"turmeric leaves","note":"tied in a knot","is_optional":true,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"palm sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Blend the shallots, garlic, soaked dried red chillies, galangal, ginger, and coriander into a smooth paste with a splash of water.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the paste in a wide heavy pot until it darkens and smells sweet rather than raw.","duration_minutes":12,"temperature":null,"tip":"A wide pot, not a deep one. The whole method depends on evaporation."},{"text":"Add the beef chuck and turn it through the paste until sealed.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Pour in the coconut milk and add the lemongrass, kaffir lime leaves, turmeric leaves, palm sugar, and salt.","duration_minutes":null,"temperature":null,"tip":"Do not cover the pot at any point."},{"text":"Simmer uncovered, stirring occasionally, until the sauce has reduced to a thick gravy.","duration_minutes":150,"temperature":"low","tip":null},{"text":"Keep going. The oil will split out and the gravy will turn dark brown — now stir constantly so the beef fries in it rather than catching.","duration_minutes":25,"temperature":null,"tip":"This is the actual cooking. The colour goes from tan to near-black and the smell changes completely."},{"text":"Serve once the beef is coated in dark paste and there is no liquid left in the pot.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["Dry {title}","{title}, Wet Style"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- iranian-ghormeh-sabzi.json
insert into sim.dish (slug, doc) values (
  $sd$iranian-ghormeh-sabzi$sd$,
  $sd${"title":"Ghormeh Sabzi","description":"The Iranian herb stew — parsley, cilantro and chives fried down until they turn almost black, then simmered slowly with lamb, kidney beans and dried limes until the whole pot tastes sour and deep. Cooks for three and a half hours, almost none of it hands-on.\n\nEvery part of this is forgiving except the herbs. Frying them down properly is the dish; rush that step and you get a green soup that tastes of lawn.","cuisine":"Iranian","category":"Main","difficulty":"hard","prep_minutes":40,"cook_minutes":210,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Herbs","ingredients":[{"quantity":300,"unit":"g","name":"parsley","note":"leaves and thin stems, finely chopped","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"cilantro","note":"leaves and thin stems, finely chopped","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"garlic chives","note":"or the green tops of spring onions","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"dried fenugreek leaves","note":"crumbled between your palms","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"vegetable oil","note":"for the herbs","is_optional":false,"food_id":null}]},{"name":"The stew","ingredients":[{"quantity":250,"unit":"g","name":"red kidney beans","note":"dried","is_optional":false,"food_id":null},{"quantity":700,"unit":"g","name":"lamb shoulder","note":"cut into 3 cm pieces, fat left on","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"finely diced","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":5,"unit":null,"name":"dried limes","note":"pierced twice with a skewer","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"vegetable oil","note":null,"is_optional":false,"food_id":null},{"quantity":1.2,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":1.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"lemon juice","note":"only if the limes have not soured it enough","is_optional":true,"food_id":null}]},{"name":"To serve","ingredients":[{"quantity":400,"unit":"g","name":"basmati rice","note":"steamed","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The night before","steps":[{"text":"Cover the red kidney beans with cool water by two fingers and leave them on the counter overnight.","duration_minutes":720,"temperature":null,"tip":"Unsoaked beans will still be chalky after three hours in an acidic pot. The limes make sure of that."},{"text":"Drain the beans, cover them with clean water, and simmer until they give under a thumbnail but still hold their shape. Drain again.","duration_minutes":50,"temperature":null,"tip":null}]},{"name":"Frying the herbs","steps":[{"text":"Warm the oil in your widest pan over a low flame and add the parsley, cilantro and chives all at once. They will fill the pan; they will not stay that way.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the herbs, stirring every few minutes, until the volume has collapsed by two thirds and the colour has gone from bright green to a dark, almost black green.","duration_minutes":35,"temperature":null,"tip":"Low and slow. If the pan is loud or the edges are browning, the heat is too high and you are frying rather than melting them."},{"text":"Stir the crumbled fenugreek leaves through for the last two minutes only.","duration_minutes":2,"temperature":null,"tip":"Fenugreek turns bitter fast. It goes in at the end, never at the start."}]},{"name":"The stew","steps":[{"text":"In a heavy pot, soften the diced onion in the remaining oil, then add the turmeric and stir for half a minute until it smells warm.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Raise the heat and brown the lamb on every side, in two batches if the pot is crowded.","duration_minutes":12,"temperature":null,"tip":"Crowded meat steams grey. Two batches costs five minutes and pays for itself in the finished colour."},{"text":"Tip in the fried herbs and the drained beans, pour over the water, and bring it to a bare simmer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Push the dried limes under the surface and leave the pot at the laziest simmer your hob will hold, lid ajar.","duration_minutes":90,"temperature":null,"tip":"Fish the limes out if the stew starts to taste medicinal rather than sour. Three hours in, they can tip over."},{"text":"Season with the salt and black pepper and cook on until a slick of oil rises to the surface and the stew is dark rather than green.","duration_minutes":45,"temperature":null,"tip":null},{"text":"Taste. If it reads flat rather than sour, add the lemon juice a spoon at a time until it sharpens.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve in shallow bowls beside steamed basmati rice, with the limes left in for whoever wants to squash one.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} with Beef","My Mother's {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- iraqi-dill-broad-bean-rice.json
insert into sim.dish (slug, doc) values (
  $sd$iraqi-dill-broad-bean-rice$sd$,
  $sd${"title":"Timman Bagilla","description":"Rice parboiled, then layered with broad beans and a great deal of dill and steamed under a cloth until a crust forms on the base. Turned out upside down so the crust is on top. Serves six alongside almost anything.\n\nFrozen broad beans are entirely fine here and save half an hour of podding. Slip them out of their grey skins if you have the patience — the colour of the finished platter is much better for it.","cuisine":"Iraqi","category":"Side","difficulty":"medium","prep_minutes":20,"cook_minutes":50,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"basmati rice","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"g","name":"broad beans","note":"podded; frozen work well","is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"dill","note":"chopped, stalks and all","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"ghee","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"pods","name":"cardamom","note":"cracked open","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"bay leaf","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1.2,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":"for the colour of the crust","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Rinse the basmati rice until the water running off it is clear, then leave it to soak in lightly salted water.","duration_minutes":30,"temperature":null,"tip":"Soaked grains lengthen instead of breaking, which is what gives the finished dish separate needles of rice rather than clumps."},{"text":"Bring the water to a hard boil with the salt, cardamom and bay leaf. Drain the rice and tip it in.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Boil for exactly seven minutes. A grain squashed between two fingers should still show a chalky line at its centre. Drain immediately.","duration_minutes":7,"temperature":null,"tip":"This is the only timed part of the recipe that matters. Fully cooked rice here becomes porridge in the steam."},{"text":"Melt the ghee in the base of the pot, stir in the turmeric, and spread a third of the rice over it in an even layer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Scatter over half the broad beans and half the dill, add another third of the rice, then the rest of the beans and dill, and finish with the last of the rice heaped into a low mound.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Wrap the lid in a tea towel, clamp it on, and steam over the lowest heat until the base has set into a crust you can hear when you tap the pot.","duration_minutes":40,"temperature":null,"tip":"Do not lift the lid to check. Sitting the pot in a sink of cold water for a minute at the end releases the crust in one piece."},{"text":"Turn it out onto a platter so the crust lands on top, and break it up at the table.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Lamb Shanks","Everyday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- israeli-shakshuka.json
insert into sim.dish (slug, doc) values (
  $sd$israeli-shakshuka$sd$,
  $sd${"title":"Shakshuka","description":"Eggs poached in a thick pepper and tomato sauce, spiced with cumin and caraway. One pan, and the sauce keeps for days without the eggs.","cuisine":"Israeli","category":"Breakfast","difficulty":"easy","prep_minutes":15,"cook_minutes":35,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"red bell peppers","note":"sliced","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"sliced","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cumin","note":"ground","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"caraway seed","note":"crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false,"food_id":null},{"quantity":800,"unit":"g","name":"tinned tomatoes","note":"crushed by hand","is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"eggs","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"feta","note":"crumbled","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"parsley","note":"chopped, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Cook the onion and red bell peppers in the olive oil until genuinely soft and beginning to catch.","duration_minutes":15,"temperature":"medium-low","tip":"This is where the sweetness comes from. Ten minutes is not enough."},{"text":"Add the garlic, cumin, caraway seed, and paprika and stir until fragrant.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the tinned tomatoes, season, and simmer until the sauce is thick enough to hold a channel when you drag a spoon through it.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Make six wells and crack an egg into each.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and cook until the whites are set and the yolks are still loose.","duration_minutes":6,"temperature":null,"tip":"Pull it a minute early — the pan carries on cooking at the table."},{"text":"Scatter over the feta and parsley.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.6,"variant_titles":["Green {title}","{title} for Two","Sunday {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- italian-tiramisu.json
insert into sim.dish (slug, doc) values (
  $sd$italian-tiramisu$sd$,
  $sd${"title":"Tiramisu","description":"Mascarpone and whipped egg over coffee-soaked savoiardi, set overnight in the fridge. No cream, no gelatine, and no baking — the structure comes entirely from the eggs.\n\nThe yolks are cooked over a bain-marie rather than left raw, which also makes the mixture more stable.","cuisine":"Italian","category":"Dessert","difficulty":"medium","prep_minutes":35,"cook_minutes":8,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":null,"name":"eggs","note":"separated","is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":500,"unit":"g","name":"mascarpone","note":"cold","is_optional":false,"food_id":null},{"quantity":300,"unit":"ml","name":"espresso","note":"strong, cooled","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"marsala","note":null,"is_optional":true,"food_id":null},{"quantity":300,"unit":"g","name":"savoiardi","note":"hard ladyfingers, not soft sponge","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"cocoa powder","note":"to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Whisk the egg yolks with the sugar over a pan of barely simmering water until pale, thick, and hot to the touch.","duration_minutes":8,"temperature":"bain-marie","tip":"Keep the bowl clear of the water and keep whisking, or you make sweet scrambled egg."},{"text":"Cool the yolk mixture, then beat in the mascarpone a spoonful at a time until smooth.","duration_minutes":null,"temperature":null,"tip":"Cold mascarpone into warm yolks will split. Let the yolks come down first."},{"text":"Whip the egg whites to soft peaks and fold them through in three additions.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Combine the espresso and marsala in a shallow dish. Dip each savoiardi for a second per side — no longer.","duration_minutes":null,"temperature":null,"tip":"They should still be firm in the middle when they go down. They keep absorbing all night."},{"text":"Layer soaked savoiardi and cream twice, finishing with cream, and smooth the top.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null},{"text":"Dust heavily with cocoa powder just before serving.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.5,"variant_titles":["{title} for a Party","Coffee-Free {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- jamaican-jerk-chicken.json
insert into sim.dish (slug, doc) values (
  $sd$jamaican-jerk-chicken$sd$,
  $sd${"title":"Jerk Chicken","description":"Chicken marinated overnight in scotch bonnet, allspice, and thyme, then cooked slowly over indirect heat. The pimento wood is the traditional smoke; a covered grill gets close.\n\nAllspice — pimento — is doing more work here than the chilli. Buy it whole and grind it.","cuisine":"Jamaican","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":75,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Jerk marinade","ingredients":[{"quantity":4,"unit":null,"name":"scotch bonnet peppers","note":"seeded for less heat","is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"spring onions","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"allspice berries","note":"freshly ground","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"thyme","note":"leaves picked","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"cm","name":"ginger","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"soy sauce","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"lime juice","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"nutmeg","note":"grated","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cinnamon","note":"ground","is_optional":false,"food_id":null}]},{"name":"Chicken","ingredients":[{"quantity":1.8,"unit":"kg","name":"chicken thighs and drumsticks","note":"bone in, skin on, slashed to the bone","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The day before","steps":[{"text":"Blend the scotch bonnet peppers, spring onions, allspice berries, thyme, garlic, ginger, soy sauce, brown sugar, lime juice, nutmeg, and cinnamon into a coarse marinade.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Work it into the slashed chicken thighs and drumsticks, getting into every cut.","duration_minutes":null,"temperature":null,"tip":"Wear gloves. Scotch bonnet oil stays on your hands for hours."},{"text":"Cover and refrigerate.","duration_minutes":720,"temperature":null,"tip":null}]},{"name":"Cooking","steps":[{"text":"Set the grill up for indirect heat — coals banked to one side, chicken on the other — and cook with the lid on.","duration_minutes":60,"temperature":"medium-low","tip":"Direct heat burns the sugar in the marinade long before the thigh is cooked through."},{"text":"Move the pieces over the coals for the last stretch to char the skin, turning often.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Rest, then chop through the bone into pieces to serve.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["Oven {title}","{title}, Mild"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- japanese-oyakodon.json
insert into sim.dish (slug, doc) values (
  $sd$japanese-oyakodon$sd$,
  $sd${"title":"Oyakodon","description":"Chicken and egg over rice, cooked in a shallow pan in about eight minutes. The egg goes in twice and never fully sets — that softness is the whole dish.","cuisine":"Japanese","category":"Main","difficulty":"easy","prep_minutes":10,"cook_minutes":10,"servings":2,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":250,"unit":"g","name":"chicken thighs","note":"boneless, cut into bite-sized pieces","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"sliced thin","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":"beaten loosely, streaks left in","is_optional":false,"food_id":null},{"quantity":150,"unit":"ml","name":"dashi","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"soy sauce","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"mirin","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"bowls","name":"steamed rice","note":"hot","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Bring the dashi, soy sauce, mirin, and sugar to a simmer in a small shallow pan.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Add the onion and cook until translucent.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Lay in the chicken in a single layer and simmer until just cooked through.","duration_minutes":4,"temperature":null,"tip":"Do not stir it about. The pieces should stay where you put them."},{"text":"Pour two-thirds of the beaten eggs over in a spiral and cover the pan.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the remaining egg, cover again, and pull the pan off the heat while the top is still visibly loose.","duration_minutes":null,"temperature":null,"tip":"Residual heat finishes it. Set egg here means you have gone too far."},{"text":"Slide over hot steamed rice and scatter with spring onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.5,"variant_titles":["10-Minute {title}","{title} for One"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- kenyan-kachumbari.json
insert into sim.dish (slug, doc) values (
  $sd$kenyan-kachumbari$sd$,
  $sd${"title":"Kachumbari","description":"A raw tomato and onion salad, sharp with lime and chilli. The onion is soaked first so it stays crisp without shouting over everything else on the plate.\n\nSalt the tomatoes on their own and let them drain. Salt them in the bowl and you will be serving soup within ten minutes.","cuisine":"Kenyan","category":"Salad","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":4,"unit":null,"name":"plum tomatoes","note":"deseeded and diced","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"red onion","note":"sliced as thin as you can manage","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"green chilli","note":"sliced into rings","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lime","note":"juiced","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"coriander","note":"leaves and thin stems","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"avocado","note":"diced","is_optional":true,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Slice the red onion paper thin and drop it into a bowl of cold water while you cut everything else.","duration_minutes":10,"temperature":null,"tip":"Ten minutes in water pulls the harsh sulphur edge off raw onion without softening it at all."},{"text":"Deseed and dice the plum tomatoes, scatter the salt over them, and leave them in a sieve to drain.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Drain the onion and press it dry between two sheets of kitchen paper.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss the tomatoes and onion with the lime juice, green chilli, and coriander, then grind over the black pepper.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fold the avocado through at the last moment and take it to the table straight away.","duration_minutes":null,"temperature":null,"tip":"This is a salad with a fifteen-minute life. Dress it when the rest of the meal is already plated."}]}],"weight":1.7,"variant_titles":["{title} with Avocado","{title}, Extra Chilli"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- korean-braised-short-ribs.json
insert into sim.dish (slug, doc) values (
  $sd$korean-braised-short-ribs$sd$,
  $sd${"title":"Korean Braised Short Ribs","description":"Galbi jjim — short ribs braised until the meat gives up and slides off the bone, in a sauce built on grated pear rather than extra sugar. A holiday dish that rewards a slow afternoon.\n\nBetter the next day. Cool the braise whole, lift the set fat off the top, and reheat gently.","cuisine":"Korean","category":"Main","difficulty":"hard","prep_minutes":30,"cook_minutes":135,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1.5,"unit":"kg","name":"beef short ribs","note":"cut into 2-inch lengths","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"soy sauce","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"brown sugar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"Asian pear","note":"peeled and grated; the enzyme is what tenderises","is_optional":false,"food_id":null},{"quantity":8,"unit":"cloves","name":"garlic","note":"smashed","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"grated","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"carrots","note":"cut into large chunks","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"daikon radish","note":"cut into large chunks","is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"shiitake mushrooms","note":"halved","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sesame oil","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"spring onions","note":"sliced, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Soak the short ribs in cold water, changing it once, to draw out the blood.","duration_minutes":60,"temperature":null,"tip":"Skipping this is the difference between a clear braise and a muddy one."},{"text":"Parboil the ribs in fresh water, then drain and rinse each piece.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Blend the pear, garlic, and ginger with the soy sauce and brown sugar into a smooth braising liquid.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Return the ribs to the pot, pour over the liquid, and simmer covered on the lowest heat.","duration_minutes":90,"temperature":"low","tip":"The meat should be pulling back from the bone before anything else goes in."},{"text":"Add the carrots, daikon, and shiitake and cook uncovered so the sauce reduces and glazes.","duration_minutes":25,"temperature":null,"tip":null},{"text":"Turn off the heat, stir through the sesame oil, and scatter with spring onions.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["Sunday {title}","{title} with Daikon"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- laotian-sticky-rice.json
insert into sim.dish (slug, doc) values (
  $sd$laotian-sticky-rice$sd$,
  $sd${"title":"Lao Sticky Rice","description":"Glutinous rice soaked overnight and steamed in a basket, not boiled. Comes out translucent and springy enough to roll into a ball with your fingers.\n\nAlmost all the work is waiting. The soak is the recipe; the steaming is twenty-five minutes of nothing. Plan it the night before or accept a chalky centre.","cuisine":"Laotian","category":"Side","difficulty":"easy","prep_minutes":10,"cook_minutes":30,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"glutinous rice","note":"long grain; sold as sweet or sticky rice, never as jasmine","is_optional":false,"food_id":null},{"quantity":null,"unit":null,"name":"water","note":"enough to cover by a hand's width, plus more for the steamer","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"banana leaf","note":"to line the basket","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Rinse the glutinous rice in several changes of water until the water stops running white.","duration_minutes":null,"temperature":null,"tip":"Four or five changes. The loose surface starch is what turns the finished rice into a gummy mass rather than separate grains."},{"text":"Cover the rice with fresh water by a good few centimetres and leave it on the counter overnight.","duration_minutes":720,"temperature":null,"tip":"This is the whole recipe. Under-soaked rice steams to a chalky core and there is no fixing it once it is in the basket."},{"text":"Drain the rice thoroughly and leave it sitting in the sieve while the steamer comes up to a hard boil.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Line the basket with the banana leaf if you have one, tip the rice in, and steam it covered until it is translucent all the way through and springy to press.","duration_minutes":25,"temperature":"high","tip":"Flip the whole mass over halfway. The layer nearest the steam cooks fastest and turning it once evens the basket out."},{"text":"Turn the rice out onto a board, spread it, and paddle it for a moment so the surface steam escapes before you pack it into a serving basket.","duration_minutes":null,"temperature":null,"tip":"Skip the paddling and the outside stays wet, which is how sticky rice ends up sticking to everyone's hands instead of to itself."}]}],"weight":1.5,"variant_titles":["{title} in a Rice Cooker","{title} with Toasted Sesame","Coconut {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- lebanese-fattoush.json
insert into sim.dish (slug, doc) values (
  $sd$lebanese-fattoush$sd$,
  $sd${"title":"Fattoush","description":"A bread salad built to use up flatbread that has gone stale. Sumac and pomegranate molasses do the work; the pita has to stay crisp until it reaches the table.\n\nDress it at the table, not in the kitchen. Fattoush has a working life of about four minutes.","cuisine":"Lebanese","category":"Salad","difficulty":"easy","prep_minutes":20,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":2,"unit":null,"name":"pita breads","note":"stale, torn into pieces and toasted crisp","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"tomatoes","note":"cut into wedges","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"Persian cucumbers","note":"roughly chopped","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"radishes","note":"sliced","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"spring onions","note":"sliced","is_optional":false,"food_id":null},{"quantity":1,"unit":"cup","name":"flat-leaf parsley","note":"leaves picked","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"mint","note":"leaves picked","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"sumac","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"pomegranate molasses","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lemon","note":"juiced","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Whisk the olive oil, lemon juice, pomegranate molasses, and half the sumac with a good pinch of salt.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Combine the tomatoes, Persian cucumbers, radishes, spring onions, parsley, and mint in a wide bowl.","duration_minutes":null,"temperature":null,"tip":"Cut everything to roughly the same size so no one component dominates a forkful."},{"text":"Add the toasted pita breads and pour over the dressing.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss once, dust with the remaining sumac, and take it straight to the table.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Purslane"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- macanese-almond-cookies.json
insert into sim.dish (slug, doc) values (
  $sd$macanese-almond-cookies$sd$,
  $sd${"title":"Macanese Almond Cookies","description":"Pressed rather than rolled, from toasted mung bean flour rubbed with cold lard. They come out sandy and dry and dissolve on the tongue. Makes about two dozen.\n\nMung bean flour is what gives these their particular chalky-in-a-good-way crumb; fine rice flour is the usual substitute and produces a slightly harder cookie. Lard is not negotiable if you want the texture — butter has water in it and water builds gluten.","cuisine":"Macanese","category":"Snack","difficulty":"easy","prep_minutes":25,"cook_minutes":20,"servings":24,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":250,"unit":"g","name":"mung bean flour","note":null,"is_optional":false,"food_id":null},{"quantity":120,"unit":"g","name":"icing sugar","note":"sifted","is_optional":false,"food_id":null},{"quantity":80,"unit":"g","name":"lard","note":"chilled hard and cut into small cubes","is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"almonds","note":"half of them ground fine, half left as halves","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"water","note":"only if the mix will not hold together","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Toast the mung bean flour in a dry pan over a low heat until it smells nutty and has lost its raw edge, then spread it out and let it cool completely.","duration_minutes":10,"temperature":"low","tip":"Cool it properly before it meets the fat. Warm flour melts the lard on contact and the sandy crumb goes with it."},{"text":"Rub the chilled lard into the flour, the icing sugar and the salt with your fingertips until it looks like damp sand, adding the water a few drops at a time only if it refuses to come together.","duration_minutes":8,"temperature":null,"tip":"Judge it by squeezing, not by looking. A handful that holds its shape when you open your fist is done; one that falls apart wants a drop more."},{"text":"Stir through the ground almonds and keep the halves back for the tops.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pack the mixture hard into a mould or a small ring, press an almond half onto each top, and knock them out onto a lined tray.","duration_minutes":15,"temperature":null,"tip":"Pack it far harder than feels reasonable. These are pressed, not rolled, and a loosely filled mould gives a cookie that slumps on the way to the oven."},{"text":"Bake until the edges are set and the tops have barely taken any colour.","duration_minutes":18,"temperature":"300°F","tip":null},{"text":"Leave them on the tray until they are stone cold before moving a single one.","duration_minutes":30,"temperature":null,"tip":"They only become structurally sound once cool. Lift one warm and it falls through your fingers."}]}],"weight":1.1,"variant_titles":["{title} with Walnut","{title}, Small Batch","Sesame {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- malaysian-curry-laksa.json
insert into sim.dish (slug, doc) values (
  $sd$malaysian-curry-laksa$sd$,
  $sd${"title":"Curry Laksa","description":"Noodles in a coconut curry broth built on a fried spice paste, with tofu puffs that soak up more soup than seems physically reasonable.","cuisine":"Malaysian","category":"Soup","difficulty":"medium","prep_minutes":30,"cook_minutes":35,"servings":4,"attribution":null,"ingredient_groups":[{"name":"Laksa paste","ingredients":[{"quantity":8,"unit":null,"name":"dried red chillies","note":"soaked","is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"shallots","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"stalks","name":"lemongrass","note":"white part only","is_optional":false,"food_id":null},{"quantity":2,"unit":"cm","name":"turmeric","note":"fresh, or 1 tsp ground","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"belacan","note":"shrimp paste, toasted","is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"candlenuts","note":"or macadamias","is_optional":false,"food_id":null}]},{"name":"Soup","ingredients":[{"quantity":400,"unit":"ml","name":"coconut milk","note":null,"is_optional":false,"food_id":null},{"quantity":800,"unit":"ml","name":"chicken stock","note":null,"is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"rice noodles","note":null,"is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"prawns","note":"peeled","is_optional":false,"food_id":null},{"quantity":8,"unit":null,"name":"tofu puffs","note":"halved","is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"bean sprouts","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"Vietnamese mint","note":"to serve","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lime","note":"cut into wedges, to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Blend the soaked dried red chillies, shallots, garlic, lemongrass, turmeric, belacan, and candlenuts into a fine paste.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the paste in oil over a medium heat until it darkens and the oil separates.","duration_minutes":15,"temperature":null,"tip":"Fifteen minutes is not an exaggeration. Underfried paste tastes raw and grainy in the finished soup."},{"text":"Add the chicken stock and bring to a simmer, then stir in the coconut milk and fish sauce.","duration_minutes":10,"temperature":null,"tip":"Keep it below a rolling boil once the coconut milk is in, or it splits."},{"text":"Add the tofu puffs and let them drink the broth.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Poach the prawns in the soup until just opaque.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Cook the rice noodles separately, divide between bowls, and ladle the soup over.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Top with bean sprouts and Vietnamese mint, and serve with lime wedges.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title}, Vegetarian","Weeknight {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- mexican-carnitas-tacos.json
insert into sim.dish (slug, doc) values (
  $sd$mexican-carnitas-tacos$sd$,
  $sd${"title":"Carnitas Tacos","description":"Pork shoulder cooked slowly in its own fat with orange and bay, then crisped hard under a broiler. Soft, rich, and shatteringly crisp in the same forkful.\n\nThe crisping step is not optional. Braised pork alone is not carnitas.","cuisine":"Mexican","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":195,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":1.8,"unit":"kg","name":"pork shoulder","note":"cut into large cubes, fat left on","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"orange","note":"halved","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"white onion","note":"quartered","is_optional":false,"food_id":null},{"quantity":6,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"bay leaves","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cumin seed","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":16,"unit":null,"name":"corn tortillas","note":"to serve","is_optional":false,"food_id":null},{"quantity":1,"unit":"bunch","name":"cilantro","note":"to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Put the pork shoulder in a heavy pot with the onion, garlic, bay leaves, cumin seed, and salt. Squeeze the orange over and drop both halves in.","duration_minutes":null,"temperature":null,"tip":"The peel goes in too — the oils in it are half the point."},{"text":"Add water to come halfway up the meat and bring to a bare simmer.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Cook uncovered on the lowest heat until the water has gone and the pork is frying in its own rendered fat.","duration_minutes":170,"temperature":"low","tip":null},{"text":"Lift the meat out, discard the bay, orange, onion, and garlic, and shred it coarsely with two forks.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Spread the shredded pork on a tray, spoon over some of the rendered fat, and broil until the edges are dark and crisp.","duration_minutes":8,"temperature":"broil","tip":"Do not stir it while it crisps, or you get steam instead of crust."},{"text":"Warm the corn tortillas, fill, and finish with cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.4,"variant_titles":["{title} with Pickled Onion","Slow {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- mongolian-buuz.json
insert into sim.dish (slug, doc) values (
  $sd$mongolian-buuz$sd$,
  $sd${"title":"Buuz","description":"Steamed lamb dumplings pleated closed with a small vent at the top. A stiff unleavened dough, a fatty filling loosened with water, and about twenty-five minutes of folding.\n\nLean mince makes a disappointing buuz. You want something around a fifth fat, because the fat melts into the water in the filling and becomes the mouthful of juice that the vent at the top is there to protect.","cuisine":"Mongolian","category":"Main","difficulty":"medium","prep_minutes":60,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"For the dough","ingredients":[{"quantity":400,"unit":"g","name":"plain flour","note":null,"is_optional":false,"food_id":null},{"quantity":220,"unit":"ml","name":"water","note":"warm","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"For the filling","ingredients":[{"quantity":500,"unit":"g","name":"minced lamb","note":"fatty, around 20 per cent","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced as finely as you can manage","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"caraway seeds","note":"lightly crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"water","note":"to loosen the filling","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Dough and filling","steps":[{"text":"Work the plain flour, salt and warm water into a stiff dough, then knead it on the bench until the surface goes smooth.","duration_minutes":10,"temperature":null,"tip":"Stiffer than feels right. A soft dough tears open the moment you start pleating it."},{"text":"Cover the dough and leave it to rest at room temperature.","duration_minutes":30,"temperature":null,"tip":"Resting is not a formality here. Unrested gluten springs back as fast as you roll it and you will fight every round."},{"text":"Chop the minced lamb further by hand if it looks pasty, then mix it with the onion, garlic, caraway seeds, salt, black pepper and the water.","duration_minutes":null,"temperature":null,"tip":"Stir in one direction for a full minute. The filling turns tacky and holds itself together while you pleat, instead of sliding out of the round."}]},{"name":"Shaping and steaming","steps":[{"text":"Roll the dough into a rope, cut it into walnut-sized pieces, and roll each one into a round that is thick in the middle and thin at the rim.","duration_minutes":25,"temperature":null,"tip":"The thick centre is structural. It is the only part carrying the weight of the filling once the buuz is standing up in the steamer."},{"text":"Pleat each round closed around a heaped spoon of filling, leaving a small opening at the very top.","duration_minutes":null,"temperature":null,"tip":"The gap is deliberate. It lets steam out so the dumpling does not split at the side and lose its juice into the tray."},{"text":"Oil the steamer tray, stand the buuz on it without letting them touch, and steam over a hard boil until the dough is glossy and no longer tastes floury.","duration_minutes":20,"temperature":"high","tip":null},{"text":"Let them sit for a minute before anyone picks one up.","duration_minutes":null,"temperature":null,"tip":"Straight out of the steamer the juice inside is hotter than the dumpling looks. One minute is the difference between a good mouthful and a burnt palate."}]}],"weight":0.8,"variant_titles":["{title} with Beef","{title}, Pan Fried","Weekend {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- moroccan-chicken-tagine.json
insert into sim.dish (slug, doc) values (
  $sd$moroccan-chicken-tagine$sd$,
  $sd${"title":"Chicken Tagine with Olives and Preserved Lemon","description":"Chicken cooked down with saffron, ginger, and a whole preserved lemon until the sauce is thick enough to coat a spoon. Salty, sour, and barely sweet.","cuisine":"Moroccan","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":60,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Chermoula","ingredients":[{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"ginger","note":"ground","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"saffron","note":"crumbled into a little warm water","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null}]},{"name":"Tagine","ingredients":[{"quantity":1.4,"unit":"kg","name":"chicken thighs","note":"bone in, skin on","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"sliced thin","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"preserved lemon","note":"flesh discarded, rind sliced","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"green olives","note":"cracked, rinsed","is_optional":false,"food_id":null},{"quantity":300,"unit":"ml","name":"chicken stock","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"bunch","name":"cilantro","note":"chopped, to finish","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Chermoula","steps":[{"text":"Pound the garlic to a paste with a little salt, then work in the ginger, paprika, turmeric, bloomed saffron, and olive oil.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Rub the chermoula into the chicken thighs and leave them to take on colour.","duration_minutes":30,"temperature":null,"tip":"An hour is better, overnight better still."}]},{"name":"Tagine","steps":[{"text":"Brown the chicken skin-side down in a heavy pot, then lift it out.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Soften the onions in the same fat until collapsing and sweet.","duration_minutes":12,"temperature":"medium-low","tip":null},{"text":"Return the chicken, pour in the chicken stock, cover, and simmer.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Add the preserved lemon rind and green olives and cook uncovered so the sauce reduces and thickens.","duration_minutes":10,"temperature":null,"tip":"Taste before adding any salt — the lemon and olives already brought plenty."},{"text":"Finish with the chopped cilantro.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- nepali-aloo-achar.json
insert into sim.dish (slug, doc) values (
  $sd$nepali-aloo-achar$sd$,
  $sd${"title":"Aloo Achar","description":"Nepali potato salad, dressed with toasted sesame ground to a powder, lemon, and mustard oil tempered with fenugreek. Timur gives it the faint numbness that makes it read as Nepali rather than as any other potato salad.\n\nDress the potatoes while they are still warm so they drink the lemon, but fold in the cucumber only at the last moment or it weeps and thins the whole bowl.","cuisine":"Nepali","category":"Salad","difficulty":"easy","prep_minutes":20,"cook_minutes":25,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":600,"unit":"g","name":"waxy potatoes","note":"scrubbed, skin on","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"sesame seeds","note":"white","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"lemon juice","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"mustard oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"timur peppercorns","note":"Sichuan peppercorns work; crush them coarsely","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"dried red chilies","note":"snapped in half","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"fenugreek seeds","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"cucumber","note":"seeded and cut into batons","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"green chili","note":"sliced thin","is_optional":true,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"cilantro","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Boil the waxy potatoes whole in salted water until a knife slides in with no resistance, then drain and let the steam dry off them.","duration_minutes":20,"temperature":null,"tip":"Whole and skin on. Cubed potatoes take on water and the dressing then slides off them."},{"text":"Toast the sesame seeds in a dry pan until they smell nutty and begin to jump, then grind them to a coarse powder.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Crush the timur peppercorns and stir them into the sesame powder with the turmeric, lemon juice and salt to make a loose paste.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Heat the mustard oil until it just begins to smoke, drop in the fenugreek seeds and the dried red chilies, and pull the pan off the heat the second the fenugreek darkens.","duration_minutes":2,"temperature":null,"tip":"Fenugreek goes from nutty to bitter in about five seconds and there is no rescuing it. Have the pan lid in your other hand."},{"text":"Cube the still-warm potatoes into a wide bowl, pour over the sesame paste and then the hot oil, and turn everything over gently.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fold through the cucumber, green chili and cilantro just before it goes to the table.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["{title} with Green Beans","{title} for a Crowd","Extra Sour {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- new-zealand-kumara-hash.json
insert into sim.dish (slug, doc) values (
  $sd$new-zealand-kumara-hash$sd$,
  $sd${"title":"Kūmara and Bacon Hash","description":"Orange kūmara parboiled, then crisped in bacon fat and left alone long enough to build a crust. Eggs cooked in wells in the pan so it all comes to the table in one dish.\n\nKūmara has more sugar in it than a potato, so it colours faster and burns sooner. Keep the pan a shade below where you would run a potato hash and give it the time back instead.","cuisine":"New Zealand","category":"Breakfast","difficulty":"easy","prep_minutes":15,"cook_minutes":30,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":700,"unit":"g","name":"kūmara","note":"orange-fleshed sweet potato, peeled and cut into 2 cm dice","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"streaky bacon","note":"cut into lardons","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"smoked paprika","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"parsley","note":"roughly chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"flaky salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":null,"name":"lemon","note":"for a squeeze at the end","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Parboil the kūmara in salted water for a few minutes until the edges are just yielding, then drain it and leave it to steam dry in the colander.","duration_minutes":6,"temperature":null,"tip":"Steam-dried edges are what crisp later. Damp dice stew in the pan and never colour."},{"text":"Fry the streaky bacon in a heavy pan until the fat has rendered out and the lardons are browning, then add the butter and the onion.","duration_minutes":8,"temperature":"medium","tip":null},{"text":"Tip in the kūmara and the smoked paprika, season with flaky salt and black pepper, and press the lot into a single layer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave the hash completely alone until a crust forms underneath, then turn it over in sections rather than stirring it.","duration_minutes":10,"temperature":"medium","tip":"Every stir resets the crust. Turn it three times in ten minutes and no more than that."},{"text":"Make four wells in the hash, crack the eggs into them, cover the pan and cook until the whites have just set.","duration_minutes":5,"temperature":"low","tip":null},{"text":"Scatter over the parsley and finish with a squeeze of lemon.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["{title} with Feta","Weekend {title}","{title} for Two"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- nigerian-jollof-rice.json
insert into sim.dish (slug, doc) values (
  $sd$nigerian-jollof-rice$sd$,
  $sd${"title":"Jollof Rice","description":"Long-grain rice braised down in a blended pepper base until every grain is stained red. The base is fried hard before the rice goes near it — that is the whole difference between jollof and tomato rice.\n\nParboiled long-grain rice is not a shortcut. It holds its shape through a long covered braise where basmati turns to porridge.","cuisine":"Nigerian","category":"Main","difficulty":"medium","prep_minutes":25,"cook_minutes":60,"servings":8,"attribution":null,"ingredient_groups":[{"name":"Pepper base","ingredients":[{"quantity":3,"unit":null,"name":"red bell peppers","note":"seeds and ribs removed","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"plum tomatoes","note":"quartered","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"scotch bonnet","note":"stem removed; halve the heat by deseeding","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"half blended, half sliced","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false,"food_id":null}]},{"name":"Rice and finish","ingredients":[{"quantity":600,"unit":"g","name":"parboiled long-grain rice","note":null,"is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"groundnut oil","note":null,"is_optional":false,"food_id":null},{"quantity":700,"unit":"ml","name":"chicken stock","note":"warm","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"curry powder","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"dried thyme","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"bay leaves","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":20,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The base","steps":[{"text":"Blend the red bell peppers, plum tomatoes, scotch bonnet, and half the onion to a smooth purée.","duration_minutes":null,"temperature":null,"tip":"Taste the raw purée before it goes in the pan. That is the only honest read you get on how hot the pot will be."},{"text":"Pour the purée into a wide pan and boil it down hard, uncovered, until it darkens and stops smelling raw.","duration_minutes":20,"temperature":null,"tip":null},{"text":"In a heavy pot, fry the sliced onion in the groundnut oil until golden, then add the tomato paste and cook it until it turns brick red.","duration_minutes":6,"temperature":null,"tip":null},{"text":"Stir the reduced purée into the paste and keep frying until oil pools at the edges of the pot.","duration_minutes":10,"temperature":null,"tip":"Wait for the oil to separate. Rice added to a wet base steams instead of frying, and it never catches up."}]},{"name":"The rice","steps":[{"text":"Rinse the parboiled rice in several changes of water until the water runs clear, then drain it well.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Add the chicken stock, curry powder, dried thyme, bay leaves, and salt to the base and bring it up to a hard boil.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Stir in the rice once, level it, seal the pot with foil under a tight lid, and cook on the lowest heat without lifting it.","duration_minutes":30,"temperature":"lowest","tip":"The foil is the recipe. Steam that escapes is water the top layer of rice never gets."},{"text":"Dot the butter over the top, fork the grains through from the bottom up, and let the pot stand off the heat before serving.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":1.4,"variant_titles":["Party {title}","Smoky {title}","One-Pot {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- pakistani-pink-tea.json
insert into sim.dish (slug, doc) values (
  $sd$pakistani-pink-tea$sd$,
  $sd${"title":"Kashmiri Pink Tea","description":"Green tea boiled down for the better part of an hour with baking soda, aerated by pouring it back on itself, shocked with iced water, and only then let anywhere near milk. The pink is a chemical trick, not a colouring.\n\nThe concentrate keeps for a week in the fridge, which is how anyone drinks this on a weekday. Make a double batch of it and the tea itself takes ten minutes.","cuisine":"Pakistani","category":"Drink","difficulty":"medium","prep_minutes":5,"cook_minutes":80,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"Tbsp","name":"green tea leaves","note":"Kashmiri or gunpowder","is_optional":false,"food_id":null},{"quantity":1,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"baking soda","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"pods","name":"cardamom","note":"cracked open","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":250,"unit":"ml","name":"iced water","note":null,"is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"whole milk","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"sugar","note":"to taste","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"pistachios","note":"slivered","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"almonds","note":"slivered","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The concentrate","steps":[{"text":"Boil the green tea leaves in half the water with the baking soda, the cardamom and the salt, uncovered.","duration_minutes":5,"temperature":null,"tip":"The baking soda is the colour. Leave it out and you get a perfectly nice pot of grey tea."},{"text":"Hold it at a rolling boil until the liquid has reduced by roughly two thirds and gone a deep reddish brown.","duration_minutes":45,"temperature":null,"tip":null},{"text":"Ladle the liquid up and pour it back into the pot from as high as you can manage without redecorating the kitchen. Keep going for a few minutes.","duration_minutes":5,"temperature":null,"tip":"Aeration is the other half of the colour. A pot that never gets air stays brown no matter how long it boils."},{"text":"Pour in the iced water in one go — the shock is what fixes the pink — then bring it back to the boil.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Add the rest of the water, boil once more, then strain the concentrate and press the leaves before discarding them.","duration_minutes":12,"temperature":null,"tip":null}]},{"name":"Serving","steps":[{"text":"Heat the milk with the sugar in a clean pan, then stir in the concentrate a ladle at a time until the colour is the pink you want.","duration_minutes":8,"temperature":null,"tip":"Roughly one part concentrate to two parts milk. Go further and it turns beige, which tastes fine and looks like nothing."},{"text":"Pour into small cups and scatter the pistachios and almonds over the top.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["Salted {title}","Everyday {title}","{title} with Extra Cream"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- peruvian-ceviche.json
insert into sim.dish (slug, doc) values (
  $sd$peruvian-ceviche$sd$,
  $sd${"title":"Peruvian Ceviche","description":"White fish cured in lime juice for minutes, not hours, with chilli, red onion, and the cloudy leftover marinade poured back over. Nothing is cooked with heat.\n\nBuy the fish the same day and keep everything cold. This is the one recipe where ingredient quality is the entire technique.","cuisine":"Peruvian","category":"Appetizer","difficulty":"easy","prep_minutes":25,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"sea bass","note":"skinless, boneless, cut into 2cm cubes; any firm white fish works","is_optional":false,"food_id":null},{"quantity":10,"unit":null,"name":"limes","note":"juiced, about 250ml","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"red onion","note":"sliced paper thin","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"aji amarillo","note":"seeded and sliced; substitute a mild yellow chilli","is_optional":false,"food_id":null},{"quantity":1,"unit":"clove","name":"garlic","note":"grated fine","is_optional":false,"food_id":null},{"quantity":1,"unit":"small piece","name":"ginger","note":"grated fine","is_optional":false,"food_id":null},{"quantity":1,"unit":"bunch","name":"cilantro","note":"chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"sweet potato","note":"boiled and sliced, to serve","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Soak the sliced red onion in ice water to take the harsh edge off, then drain it well.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Whisk the lime juice with the grated garlic, ginger, and salt to make the leche de tigre.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Toss the sea bass with the salt and let it sit briefly before the acid goes anywhere near it.","duration_minutes":2,"temperature":null,"tip":"Salting first firms the surface so the fish cures evenly instead of going chalky outside and raw inside."},{"text":"Pour the leche de tigre over the fish and stir once.","duration_minutes":3,"temperature":null,"tip":"Three minutes. The cubes should turn opaque at the edge and stay translucent at the centre."},{"text":"Fold through the drained onion, aji amarillo, and cilantro, and serve immediately with sliced sweet potato.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} with Mango"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- polish-pierogi-ruskie.json
insert into sim.dish (slug, doc) values (
  $sd$polish-pierogi-ruskie$sd$,
  $sd${"title":"Pierogi Ruskie","description":"Dumplings filled with potato and twarog, boiled and then fried in butter with onions. The dough is worked warm and rested, which is what keeps it from tearing.\n\nFreeze them raw on a tray before bagging, and boil from frozen. They do not survive being stacked wet.","cuisine":"Polish","category":"Main","difficulty":"hard","prep_minutes":70,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"Dough","ingredients":[{"quantity":500,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":250,"unit":"ml","name":"water","note":"warm","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"butter","note":"melted","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Filling","ingredients":[{"quantity":600,"unit":"g","name":"potatoes","note":"boiled and riced","is_optional":false,"food_id":null},{"quantity":250,"unit":"g","name":"twarog","note":"farmer's cheese; substitute dry ricotta","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"one for the filling, one to serve","is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"white pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Dough","steps":[{"text":"Mix the flour and salt with the warm water and melted butter, then knead until smooth and elastic.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Cover and rest the dough.","duration_minutes":30,"temperature":null,"tip":"Unrested dough springs back while you are trying to fill it and the seals fail."}]},{"name":"Filling","steps":[{"text":"Fry one diced onion in half the butter until deep golden.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Mash the fried onion into the riced potatoes and twarog with the white pepper and plenty of salt, and let it cool completely.","duration_minutes":null,"temperature":null,"tip":"Taste it and over-season slightly — the dough around it is unsalted."}]},{"name":"Shaping and cooking","steps":[{"text":"Roll the dough thin and cut rounds, keeping the offcuts covered as you go.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Place a spoonful of filling on each round, fold, and pinch the edge firmly all the way along.","duration_minutes":null,"temperature":null,"tip":"Wet fingers make the seal worse, not better. Dry, firm pressure holds."},{"text":"Boil in well-salted water in batches until they float, then give them another minute.","duration_minutes":12,"temperature":null,"tip":null},{"text":"Fry the remaining sliced onion in the rest of the butter and toss the drained pierogi through it.","duration_minutes":8,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["Grandmother's {title}","{title} with Bacon"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- portuguese-pastel-de-nata.json
insert into sim.dish (slug, doc) values (
  $sd$portuguese-pastel-de-nata$sd$,
  $sd${"title":"Pastéis de Nata","description":"Custard tarts baked in the hottest oven you have, so the tops blister black while the centre stays loose. The pastry is rolled into a log and cut, not lined.\n\nMakes 12. Domestic ovens rarely reach the 300°C these want; go as hot as yours goes and put the tray on the floor of the oven.","cuisine":"Portuguese","category":"Dessert","difficulty":"hard","prep_minutes":45,"cook_minutes":15,"servings":12,"attribution":null,"ingredient_groups":[{"name":"Custard","ingredients":[{"quantity":250,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"stick","name":"cinnamon","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lemon","note":"peel in strips, no pith","is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"milk","note":null,"is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":6,"unit":null,"name":"egg yolks","note":null,"is_optional":false,"food_id":null}]},{"name":"Pastry","ingredients":[{"quantity":400,"unit":"g","name":"puff pastry","note":"all butter, at room temperature","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Custard","steps":[{"text":"Boil the sugar and water with the cinnamon stick and lemon peel to a thin syrup, then set it aside to infuse.","duration_minutes":5,"temperature":"220°F","tip":null},{"text":"Whisk the flour into a little of the cold milk to a smooth slurry, then stir in the rest of the milk and cook until thickened.","duration_minutes":6,"temperature":null,"tip":"Lumps here cannot be fixed later. Slurry first, always."},{"text":"Strain the warm syrup into the hot milk mixture in a steady stream, whisking.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Let it cool below blood heat, then whisk in the egg yolks and strain the custard.","duration_minutes":15,"temperature":null,"tip":"Yolks into anything hotter than this scramble instantly."}]},{"name":"Shaping and baking","steps":[{"text":"Roll the puff pastry into a tight log, cut it into 12 discs, and press each cut-side-down into a muffin tin, thumbing it up the sides.","duration_minutes":null,"temperature":null,"tip":"Cut side down is what gives the layered spiral on the base."},{"text":"Chill the cases while the oven heats as high as it will go.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Fill each case three-quarters full and bake until the tops are blistered and blackened in patches.","duration_minutes":15,"temperature":"as hot as the oven goes","tip":"The black spots are correct. Pale tarts are underbaked."},{"text":"Cool briefly and eat warm, dusted with cinnamon.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["{title}, Shortcut Pastry"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- puerto-rican-tostones.json
insert into sim.dish (slug, doc) values (
  $sd$puerto-rican-tostones$sd$,
  $sd${"title":"Tostones with Garlic Mojo","description":"Green plantains fried once, smashed flat, and fried again so the edges shatter and the middle stays soft. The mojo alongside is raw — garlic, citrus, oil, nothing cooked.\n\nGreen means green. A plantain with any yellow showing has started turning its starch to sugar, and it will brown long before it crisps.","cuisine":"Puerto Rican","category":"Side","difficulty":"easy","prep_minutes":15,"cook_minutes":15,"servings":4,"attribution":null,"ingredient_groups":[{"name":"Tostones","ingredients":[{"quantity":3,"unit":null,"name":"green plantains","note":null,"is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"neutral oil","note":"for frying","is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"warm water","note":"for the dip between fries","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Garlic mojo","ingredients":[{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"orange juice","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"lime juice","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"dried oregano","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"sea salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Mojo","steps":[{"text":"Crush the garlic to a paste with the sea salt, then stir in the olive oil, orange juice, lime juice, and dried oregano.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave the mojo to sit while you fry, so the raw garlic loses its edge.","duration_minutes":15,"temperature":null,"tip":"Crushing with salt does the work a blender cannot — it breaks the cell walls without whipping air into the oil."}]},{"name":"Tostones","steps":[{"text":"Score the skin of the green plantains along their ridges, peel them under running water, and cut them into thick coins.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the coins in the neutral oil over a moderate heat until pale gold and just tender, then lift them onto paper.","duration_minutes":8,"temperature":"160°C / 320°F","tip":null},{"text":"Smash each coin flat between two plates or a folded sheet of baking paper.","duration_minutes":null,"temperature":null,"tip":"Smash them while they are hot. A cooled coin splits into three pieces instead of flattening."},{"text":"Dip each flattened piece briefly in the warm water, shake it off hard, and fry it again in hotter oil until it is crisp at the rim.","duration_minutes":7,"temperature":"190°C / 375°F","tip":null},{"text":"Drain them, hit them with the salt while they are still shining, and serve with the mojo.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["{title}, Double Fried","{title} and Cilantro"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- russian-blini.json
insert into sim.dish (slug, doc) values (
  $sd$russian-blini$sd$,
  $sd${"title":"Buckwheat Blini","description":"Yeast-raised buckwheat pancakes, left to ferment overnight so they come out sour and lacy rather than sweet. Served with sour cream and whatever is salty.\n\nThe overnight rise is the flavour. A one-hour version works and tastes like a plain pancake.","cuisine":"Russian","category":"Breakfast","difficulty":"medium","prep_minutes":20,"cook_minutes":25,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":150,"unit":"g","name":"buckwheat flour","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":500,"unit":"ml","name":"milk","note":"warm","is_optional":false,"food_id":null},{"quantity":7,"unit":"g","name":"instant yeast","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"eggs","note":"separated","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":"melted, plus more for the pan","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"sour cream","note":"to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The night before","steps":[{"text":"Whisk the buckwheat flour, all-purpose flour, instant yeast, and warm milk into a loose batter.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and leave at room temperature to ferment.","duration_minutes":600,"temperature":null,"tip":"It should smell distinctly sour in the morning and be covered in bubbles."}]},{"name":"Morning","steps":[{"text":"Beat in the egg yolks, salt, and melted butter.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Whip the egg whites to soft peaks and fold them through.","duration_minutes":null,"temperature":null,"tip":"Fold, do not stir. The air is what makes them lacy."},{"text":"Cook spoonfuls in a buttered pan over a medium heat until the surface is covered in holes, then turn.","duration_minutes":25,"temperature":"medium","tip":null},{"text":"Serve hot with sour cream.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} with Smoked Fish","Quick {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- senegalese-thieboudienne.json
insert into sim.dish (slug, doc) values (
  $sd$senegalese-thieboudienne$sd$,
  $sd${"title":"Thieboudienne","description":"Fish stuffed with a pounded herb paste, simmered with root vegetables, and then rice cooked in that same broth until it has taken on everything. One pot, three stages, and it wants a Sunday.\n\nThe prized part is the toasted crust at the bottom of the pot. Scrape it up and serve it over the rice, not hidden underneath it.","cuisine":"Senegalese","category":"Main","difficulty":"hard","prep_minutes":45,"cook_minutes":95,"servings":8,"attribution":null,"ingredient_groups":[{"name":"Rof, the herb stuffing","ingredients":[{"quantity":1,"unit":"bunch","name":"flat-leaf parsley","note":"stems included","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"spring onions","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"scotch bonnet","note":"deseeded","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Fish and vegetables","ingredients":[{"quantity":1.2,"unit":"kg","name":"grouper steaks","note":"cut thick, on the bone","is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"peanut oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"sliced","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"plum tomatoes","note":"chopped","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"tamarind paste","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"carrots","note":"in thick lengths","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"cassava","note":"peeled, in batons","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"aubergine","note":"quartered","is_optional":false,"food_id":null},{"quantity":0.5,"unit":null,"name":"white cabbage","note":"in wedges, core left on","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]},{"name":"Rice","ingredients":[{"quantity":600,"unit":"g","name":"broken rice","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Rof and fish","steps":[{"text":"Pound the flat-leaf parsley, garlic, spring onions, scotch bonnet, and salt to a coarse green paste.","duration_minutes":null,"temperature":null,"tip":"Pound it, do not blend it. A processor makes a smooth sauce that runs out of the fish the moment it hits the broth."},{"text":"Cut a deep pocket into each grouper steak and pack the paste in, pressing it back into the flesh so nothing shows.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Leave the stuffed fish in the fridge while you start the broth.","duration_minutes":30,"temperature":null,"tip":null}]},{"name":"The broth","steps":[{"text":"Fry the onions in the peanut oil in a wide heavy pot until soft, then add the tomato paste and the plum tomatoes and cook them down to a dark jam.","duration_minutes":12,"temperature":null,"tip":null},{"text":"Slide the fish in, pour over the water, stir in the tamarind paste, and simmer gently until the fish is just set, then lift each piece out and keep it warm.","duration_minutes":20,"temperature":null,"tip":"The fish comes out before it is fully done. It goes back on top of a hot platter at the end and finishes there."},{"text":"Cook the carrots, cassava, aubergine, and white cabbage in the broth in that order, pulling each one out the moment it gives to a knife.","duration_minutes":25,"temperature":null,"tip":null},{"text":"Taste the broth and season it with black pepper until it is stronger than you would want to drink — the rice will take half of it away.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"The rice","steps":[{"text":"Rinse the broken rice, then stir it into the reduced broth and level the surface.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cover and cook on a low heat without stirring, until the rice is tender and you can smell a crust forming underneath.","duration_minutes":30,"temperature":"low","tip":"Stirring is what turns this into a stew. Leave it alone and let the bottom toast."},{"text":"Pile the rice onto a platter, arrange the fish and vegetables over it, and scrape the crust up and scatter it on top.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.5,"variant_titles":["Grand {title}","{title} with Extra Rof"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- serbian-ajvar.json
insert into sim.dish (slug, doc) values (
  $sd$serbian-ajvar$sd$,
  $sd${"title":"Ajvar","description":"Roasted red pepper relish cooked down until a spoon dragged through it leaves a track. An autumn job done in bulk — this makes roughly three jars, sixteen servings of a spoonful each on bread.\n\nLong red horn peppers have thick walls and low water, which is why they are worth hunting down. Bell peppers work but give a thinner, sweeter result and take longer to cook down.","cuisine":"Serbian","category":"Sauce","difficulty":"medium","prep_minutes":40,"cook_minutes":120,"servings":16,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"kg","name":"red peppers","note":"long horn peppers if you can find them","is_optional":false,"food_id":null},{"quantity":500,"unit":"g","name":"aubergines","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"crushed to a paste","is_optional":false,"food_id":null},{"quantity":150,"unit":"ml","name":"sunflower oil","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"chilli","note":"finely chopped","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Roast the red peppers and the aubergines whole in a hot oven, turning them, until the skins are blistered and black in patches all over.","duration_minutes":40,"temperature":"230°C / 450°F","tip":null},{"text":"Tip the hot vegetables into a bowl, cover it, and leave them to steam themselves loose.","duration_minutes":20,"temperature":null,"tip":"Steaming is what lets the skin slide off in sheets. Peel them straight from the oven and you spend an hour picking at scraps."},{"text":"Peel, stem, and seed everything, then leave the flesh piled in a colander overnight to drain.","duration_minutes":600,"temperature":null,"tip":"This is the step people skip and then wonder why their ajvar is soup. Drained flesh fries; wet flesh boils."},{"text":"Chop the drained flesh coarsely by hand, or pulse it in short bursts — it should keep some body rather than become a purée.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cook it in the sunflower oil over low heat, stirring often, until it darkens to brick red and a spoon dragged across the base leaves a channel that stays open.","duration_minutes":75,"temperature":null,"tip":"The whole cook is just driving off water. Stop when the channel holds for a count of three — any further and it turns to paste on cooling."},{"text":"Stir in the garlic, chilli, salt, sugar, and red wine vinegar and cook a few minutes more to take the raw edge off.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Pot it into warm sterilised jars while hot and float a thin film of oil over the surface of each.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["Hot {title}","Smoky {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- singaporean-hainanese-chicken-rice.json
insert into sim.dish (slug, doc) values (
  $sd$singaporean-hainanese-chicken-rice$sd$,
  $sd${"title":"Hainanese Chicken Rice","description":"A whole bird poached below a simmer, shocked in ice water, and served at room temperature over rice cooked in its own broth and fat. Two sauces on the side, both mandatory.\n\nFour components, and the rice is the one people underestimate. It is not a side — it carries the fat and the broth, and a dry, plain bowl of rice under good chicken is a failed plate.","cuisine":"Singaporean","category":"Main","difficulty":"hard","prep_minutes":35,"cook_minutes":60,"servings":4,"attribution":null,"ingredient_groups":[{"name":"For the chicken","ingredients":[{"quantity":1,"unit":null,"name":"whole chicken","note":"about 1.6 kg, at room temperature","is_optional":false,"food_id":null},{"quantity":3,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":5,"unit":"cm","name":"ginger","note":"sliced","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"scallions","note":"halved","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sesame oil","note":"for brushing","is_optional":false,"food_id":null},{"quantity":null,"unit":null,"name":"ice water","note":"a large bowlful, for the plunge","is_optional":false,"food_id":null}]},{"name":"For the rice","ingredients":[{"quantity":2,"unit":"cups","name":"jasmine rice","note":"rinsed until the water runs clear, then drained","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"chicken fat","note":"trimmed from the cavity of the bird","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"finely chopped","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"shallots","note":"finely chopped","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"pandan leaves","note":"knotted","is_optional":true,"food_id":null},{"quantity":600,"unit":"ml","name":"poaching broth","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"For the ginger and scallion oil","ingredients":[{"quantity":60,"unit":"g","name":"ginger","note":"grated to a pulp","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"scallions","note":"sliced as thinly as you can","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":80,"unit":"ml","name":"peanut oil","note":null,"is_optional":false,"food_id":null}]},{"name":"For the chilli sauce","ingredients":[{"quantity":8,"unit":null,"name":"red chillies","note":"seeds left in","is_optional":false,"food_id":null},{"quantity":3,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"cm","name":"ginger","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"lime juice","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"poaching broth","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Poach the chicken","steps":[{"text":"Rub the whole chicken inside and out with the salt, then rinse it clean. Pull the pads of chicken fat out of the cavity and set them aside.","duration_minutes":null,"temperature":null,"tip":"That fat is the entire point of the rice. Do not bin it."},{"text":"Bring the water to a boil with the ginger and scallions, lower the bird in breast down, and immediately drop the heat until the surface stops moving.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Poach until the thickest part of the thigh is just done, turning the bird once halfway.","duration_minutes":35,"temperature":"low","tip":"The water must never bubble. If it does, the breast tightens and no amount of resting brings it back."},{"text":"Lift the chicken out and plunge it into ice water until it is cold right through, then brush it all over with sesame oil.","duration_minutes":10,"temperature":null,"tip":"The cold shock is what sets the slippery jelly layer under the skin that people queue for."}]},{"name":"Cook the rice","steps":[{"text":"Render the reserved chicken fat in a pan over low heat, then fry the garlic and shallots in it until pale gold.","duration_minutes":6,"temperature":"low","tip":null},{"text":"Stir in the drained jasmine rice and toast it until every grain is coated and turning translucent at the edges.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Add the poaching broth, the pandan leaves and the salt, then cook the rice covered until the liquid is gone and the grains are separate.","duration_minutes":15,"temperature":null,"tip":"Measure the broth rather than reusing your plain-rice ratio. The fat means it needs slightly less liquid than you expect."}]},{"name":"The two sauces","steps":[{"text":"Put the ginger, scallions and salt in a heatproof bowl. Heat the peanut oil until it shimmers and pour it straight over.","duration_minutes":null,"temperature":null,"tip":"It should sizzle hard for a couple of seconds. If it does not, the oil was too cool and the ginger stays raw and hot."},{"text":"Blend the red chillies, garlic, ginger, lime juice, sugar, salt and the poaching broth into a loose, pourable sauce.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Serve","steps":[{"text":"Carve the chicken onto a plate at room temperature, serve the rice alongside, and put both sauces and a small bowl of the remaining broth on the table.","duration_minutes":null,"temperature":null,"tip":"Room temperature, not fridge cold and not hot. Straight from the ice bath it tastes of nothing; reheated it may as well be a roast."}]}],"weight":0.6,"variant_titles":["{title} for a Crowd","Weeknight {title}","{title} with Extra Chilli"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- south-african-malva-pudding.json
insert into sim.dish (slug, doc) values (
  $sd$south-african-malva-pudding$sd$,
  $sd${"title":"Malva Pudding","description":"A sticky apricot jam sponge that has hot cream sauce poured over it straight from the oven and drinks all of it. Served warm, never cold.\n\nThe sauce must go on while both the pudding and the sauce are hot. Cold sauce sits on top instead of soaking in.","cuisine":"South African","category":"Dessert","difficulty":"medium","prep_minutes":20,"cook_minutes":45,"servings":8,"attribution":null,"ingredient_groups":[{"name":"Pudding","ingredients":[{"quantity":200,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"eggs","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"apricot jam","note":null,"is_optional":false,"food_id":null},{"quantity":220,"unit":"g","name":"all-purpose flour","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"baking soda","note":null,"is_optional":false,"food_id":null},{"quantity":200,"unit":"ml","name":"milk","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"white vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":30,"unit":"g","name":"butter","note":"melted","is_optional":false,"food_id":null}]},{"name":"Sauce","ingredients":[{"quantity":200,"unit":"ml","name":"heavy cream","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"butter","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"ml","name":"hot water","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Pudding","steps":[{"text":"Beat the sugar and eggs until thick and pale, then beat in the apricot jam and melted butter.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Stir the baking soda into the milk with the white vinegar — it will froth — and fold it into the batter with the flour.","duration_minutes":null,"temperature":null,"tip":"Work quickly once the soda and vinegar meet. The lift starts immediately."},{"text":"Pour into a buttered dish and bake until risen and deep brown.","duration_minutes":45,"temperature":"350°F","tip":null}]},{"name":"Sauce","steps":[{"text":"Warm the heavy cream, butter, sugar, and hot water together until the sugar dissolves.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Prick the hot pudding all over and pour the hot sauce over it in stages, letting each addition disappear.","duration_minutes":null,"temperature":null,"tip":"It will look like far too much liquid. It is not."},{"text":"Stand before serving so the sponge finishes absorbing.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- spanish-seafood-paella.json
insert into sim.dish (slug, doc) values (
  $sd$spanish-seafood-paella$sd$,
  $sd${"title":"Seafood Paella","description":"Rice cooked flat in a wide pan and never stirred, so the bottom layer caramelises into socarrat. The seafood goes in late and stays whole.\n\nUse the widest pan you own. Depth is the enemy — the rice should sit no more than two grains deep.","cuisine":"Spanish","category":"Main","difficulty":"hard","prep_minutes":25,"cook_minutes":40,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":400,"unit":"g","name":"bomba rice","note":"or another short-grain paella rice","is_optional":false,"food_id":null},{"quantity":1.2,"unit":"L","name":"fish stock","note":"hot","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"saffron","note":"bloomed in a little hot stock","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"prawns","note":"shell on","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"mussels","note":"scrubbed and debearded","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"squid","note":"cut into rings","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced fine","is_optional":false,"food_id":null},{"quantity":3,"unit":"cloves","name":"garlic","note":"minced","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"tomatoes","note":"grated, skins discarded","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"sweet paprika","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"lemon","note":"cut into wedges, to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Sear the prawns and squid briefly in the olive oil and set them aside — they will finish later.","duration_minutes":3,"temperature":null,"tip":null},{"text":"In the same pan, cook the onion and garlic down, then add the grated tomatoes and sweet paprika and reduce to a dark sofrito.","duration_minutes":12,"temperature":null,"tip":"The sofrito should be jammy and almost dry. This is where most of the flavour lives."},{"text":"Stir in the bomba rice and coat it in the sofrito.","duration_minutes":2,"temperature":null,"tip":null},{"text":"Pour in the hot fish stock and the bloomed saffron, spread the rice level, and do not stir again.","duration_minutes":null,"temperature":null,"tip":"From this point a spoon is forbidden. Stirring releases starch and you get risotto."},{"text":"Cook at a strong simmer, turning the pan for even heat.","duration_minutes":12,"temperature":"medium-high","tip":null},{"text":"Push the mussels into the rice hinge-down, return the prawns and squid to the top, and cook until the liquid has gone.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Raise the heat for the last minute to build the socarrat — listen for it crackling.","duration_minutes":2,"temperature":"high","tip":null},{"text":"Rest off the heat under a cloth, then serve with lemon wedges.","duration_minutes":5,"temperature":null,"tip":null}]}],"weight":0.9,"variant_titles":["{title} for Six","Mixed {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- sri-lankan-ambul-thiyal.json
insert into sim.dish (slug, doc) values (
  $sd$sri-lankan-ambul-thiyal$sd$,
  $sd${"title":"Ambul Thiyal","description":"Sour fish curry with almost no sauce: cubes of tuna blackened with crushed pepper and goraka, then cooked down in a shallow pan until the liquid has gone and what is left clings to the fish. Keeps for days without a fridge, which is the whole point of it.\n\nIt should taste sour first and hot second. If you are using tamarind instead of goraka, start with less than you think — tamarind is sharper and sweeter, and it can bully the pepper out of the dish.","cuisine":"Sri Lankan","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":45,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":700,"unit":"g","name":"tuna steaks","note":"cut into 4 cm cubes","is_optional":false,"food_id":null},{"quantity":8,"unit":"pieces","name":"goraka","note":"or 2 Tbsp thick tamarind paste","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"black peppercorns","note":"coarsely crushed, not powdered","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"chili powder","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"turmeric","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"sprig","name":"curry leaves","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"piece","name":"pandan leaf","note":"a 10 cm length","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"sliced","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"ginger","note":"cut into fine strips","is_optional":false,"food_id":null},{"quantity":1,"unit":"stick","name":"cinnamon","note":"a 5 cm piece","is_optional":false,"food_id":null},{"quantity":1.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"ml","name":"water","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Soak the goraka in warm water until the pieces soften, then pound them with the salt to a rough dark paste.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Turn the tuna cubes through the goraka paste with the crushed peppercorns, chili powder and turmeric until every face of every piece is coated black.","duration_minutes":null,"temperature":null,"tip":"Use your hands and take a minute over it. Any bare patch will cook pale and taste of nothing."},{"text":"Pack the fish into a single layer in a clay pot or a heavy shallow pan and tuck the garlic, ginger, cinnamon, pandan leaf and curry leaves into the gaps.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pour in the water, cover, and cook at a bare simmer without stirring.","duration_minutes":25,"temperature":null,"tip":"Shake the pan by the handle if you must move things. A spoon breaks the cubes and then it is fish paste, not ambul thiyal."},{"text":"Take the lid off and cook on until barely any liquid is left and what remains is a dark glaze on the fish.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Let it stand off the heat before serving. It is better warm than hot, and better again the next day.","duration_minutes":15,"temperature":null,"tip":null}]}],"weight":0.8,"variant_titles":["{title} with Kingfish","Extra Hot {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- swedish-gravlax.json
insert into sim.dish (slug, doc) values (
  $sd$swedish-gravlax$sd$,
  $sd${"title":"Dill-Cured Gravlax","description":"A side of salmon buried in salt, sugar, and dill for two days. No heat touches it — the cure does all the work — and it keeps a week once sliced. Served as a starter for ten with a sweet mustard sauce.\n\nThe salt-to-sugar ratio is the recipe. Roughly equal by volume gives a cure that seasons rather than pickles; push the salt up and you get something closer to lox, which is a different thing entirely.","cuisine":"Swedish","category":"Appetizer","difficulty":"medium","prep_minutes":20,"cook_minutes":0,"servings":10,"attribution":null,"ingredient_groups":[{"name":"For the cure","ingredients":[{"quantity":1,"unit":"side","name":"salmon fillet","note":"skin on, about 1 kg, pin bones out","is_optional":false,"food_id":null},{"quantity":90,"unit":"g","name":"sea salt","note":"coarse","is_optional":false,"food_id":null},{"quantity":70,"unit":"g","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"white peppercorns","note":"crushed, not powdered","is_optional":false,"food_id":null},{"quantity":2,"unit":"bunches","name":"dill","note":"stems and all, chopped","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"aquavit","note":null,"is_optional":true,"food_id":null}]},{"name":"For the mustard sauce","ingredients":[{"quantity":3,"unit":"Tbsp","name":"sweet mustard","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"Dijon mustard","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"white wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"ml","name":"neutral oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"dill","note":"finely chopped","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"Cure","steps":[{"text":"Run a fingertip down the centre of the salmon fillet against the grain and pull out every pin bone you find with tweezers.","duration_minutes":null,"temperature":null,"tip":"Do this before the cure, not after. Cured flesh tears where a bone comes out and the slices show it."},{"text":"Mix the sea salt, sugar, and crushed white peppercorns, then work the chopped dill and the aquavit through until the whole lot is damp and green.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Lay the fillet skin down on a large sheet of cling film, pack the cure over every part of the flesh, and wrap it tightly enough that nothing can escape.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Set the parcel in a dish, weight it with a plate and two tins, and refrigerate. Turn it over once a day and pour off the liquid that collects.","duration_minutes":2880,"temperature":null,"tip":"The pooled liquid is the cure working, not a leak. Leave the fish sitting in it and the surface goes soft and grey."},{"text":"Unwrap, scrape the cure away with the back of a knife, and pat the surface dry.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Sauce and serving","steps":[{"text":"Whisk the sweet mustard, Dijon mustard, white wine vinegar, and sugar together, then trickle in the neutral oil while whisking until it thickens to a pourable cream.","duration_minutes":null,"temperature":null,"tip":"Trickle means trickle. Half the oil at once and the sauce splits into a slick you cannot bring back."},{"text":"Stir the finely chopped dill through the sauce and leave it to sit while you slice.","duration_minutes":15,"temperature":null,"tip":null},{"text":"Slice the cured side thinly on a long shallow angle, starting at the tail, leaving the skin behind on the board.","duration_minutes":null,"temperature":null,"tip":"A long flexible blade and slices you can almost read a newspaper through. Thick gravlax just eats salty."}]}],"weight":0.7,"variant_titles":["{title} with Beetroot","Juniper {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- swiss-rosti.json
insert into sim.dish (slug, doc) values (
  $sd$swiss-rosti$sd$,
  $sd${"title":"Rösti","description":"A single pan-sized potato cake, crisp on both faces and steamy in the middle. Made from potatoes boiled the day before, because cold cooked potato is the only kind that grates into strands.\n\nA 24 cm heavy pan gives a cake about 2 cm thick, which is the depth that crisps properly. Thicker than that and the centre stays raw-tasting while the crust burns.","cuisine":"Swiss","category":"Side","difficulty":"medium","prep_minutes":15,"cook_minutes":50,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":900,"unit":"g","name":"waxy potatoes","note":"cooked the day before, skins on","is_optional":false,"food_id":null},{"quantity":60,"unit":"g","name":"butter","note":"clarified if you can","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"neutral oil","note":null,"is_optional":false,"food_id":null},{"quantity":1.5,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"nutmeg","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Boil the waxy potatoes in their skins until a knife meets clear resistance in the middle — under-done rather than done.","duration_minutes":20,"temperature":null,"tip":null},{"text":"Drain, cool completely, and refrigerate uncovered overnight.","duration_minutes":720,"temperature":null,"tip":"This is the step the whole recipe turns on. Cold potato grates into strands; warm potato grates into paste, and paste fries into a flat wet disc."},{"text":"Peel the chilled potatoes with your thumb and grate them on the coarse side of a box grater into a wide bowl.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Season with the salt, black pepper, and nutmeg, lifting the strands with your fingertips rather than stirring.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Heat the butter with the neutral oil in a heavy pan and tip the potato in, spreading it out without pressing.","duration_minutes":null,"temperature":null,"tip":"Loose is what lets steam escape from the middle. Press now and you have compacted it into a dumpling."},{"text":"Fry over medium heat until the underside is one solid brown sheet that moves as a single piece when you shake the pan.","duration_minutes":15,"temperature":null,"tip":"Press the cake down flat only in the last two minutes, once the crust has already formed."},{"text":"Slide it onto a plate, invert the pan over it, turn the pair together, and fry the second side.","duration_minutes":12,"temperature":null,"tip":null}]}],"weight":1.2,"variant_titles":["{title} with Bacon and Onion","Cheesy {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- syrian-muhammara.json
insert into sim.dish (slug, doc) values (
  $sd$syrian-muhammara$sd$,
  $sd${"title":"Muhammara","description":"Roasted red peppers and walnuts pounded into a coarse, brick-red dip, sharpened with pomegranate molasses and Aleppo pepper. Nothing is cooked — it is fifteen minutes and a food processor, and it is better made an hour ahead.\n\nJarred peppers are what make this a no-cook dish. If you would rather roast your own, blacken and peel three large red peppers first and let them drain properly — the texture is better and the timing is no longer fifteen minutes.","cuisine":"Syrian","category":"Appetizer","difficulty":"easy","prep_minutes":15,"cook_minutes":0,"servings":6,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":400,"unit":"g","name":"roasted red peppers","note":"from a jar, drained","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"walnuts","note":null,"is_optional":false,"food_id":null},{"quantity":40,"unit":"g","name":"breadcrumbs","note":"coarse and dry","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"pomegranate molasses","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"olive oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cumin","note":"ground","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"Aleppo pepper","note":"or more, to taste","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"lemon juice","note":null,"is_optional":false,"food_id":null},{"quantity":0.75,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Drain the roasted red peppers and pat them dry between two tea towels until they stop leaving damp marks.","duration_minutes":null,"temperature":null,"tip":"Wet peppers are the single reason muhammara turns into a puddle in the bowl. Take this further than feels necessary."},{"text":"Pulse the walnuts and breadcrumbs together until they look like coarse wet sand.","duration_minutes":null,"temperature":null,"tip":"Stop while you can still see individual pieces. Once it goes to paste the dip loses its grain and reads as hummus."},{"text":"Add the peppers, garlic, cumin, Aleppo pepper, salt, pomegranate molasses and lemon juice, and pulse in short bursts until it comes together but stays rough.","duration_minutes":null,"temperature":null,"tip":null},{"text":"With the motor running slowly, pour in the olive oil until the mixture turns glossy and holds a spoon mark.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Taste and push it one way or the other — more molasses for sweetness, more lemon for edge, more Aleppo for heat. Spread it into a shallow bowl and leave it to settle.","duration_minutes":60,"temperature":null,"tip":"Straight out of the processor it tastes disjointed. An hour on the counter is what pulls it into one thing."}]}],"weight":1.3,"variant_titles":["{title} with Extra Chili","Smoky {title}","{title}, Walnut Free"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- taiwanese-beef-noodle-soup.json
insert into sim.dish (slug, doc) values (
  $sd$taiwanese-beef-noodle-soup$sd$,
  $sd${"title":"Taiwanese Beef Noodle Soup","description":"Shin braised for three hours in a broth built on fermented broad bean paste, tomatoes and whole spice. The bowl is assembled at the last minute so the noodles never sit in the soup.\n\nThere is a clear-broth camp and a red-braised camp, and this is firmly the second. The tomatoes are not a shortcut — they thin the bean paste and give the broth a sweetness that sugar alone cannot.","cuisine":"Taiwanese","category":"Soup","difficulty":"hard","prep_minutes":30,"cook_minutes":180,"servings":6,"attribution":null,"ingredient_groups":[{"name":"For the broth","ingredients":[{"quantity":1.2,"unit":"kg","name":"beef shin","note":"cut into large chunks, sinew left on","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"beef tallow","note":"or a neutral oil","is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"doubanjiang","note":"fermented broad bean chilli paste","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"halved","is_optional":false,"food_id":null},{"quantity":6,"unit":"cloves","name":"garlic","note":"crushed flat","is_optional":false,"food_id":null},{"quantity":5,"unit":"cm","name":"ginger","note":"sliced into coins","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"scallions","note":"cut into finger lengths","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"tomatoes","note":"quartered","is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"soy sauce","note":null,"is_optional":false,"food_id":null},{"quantity":60,"unit":"ml","name":"Shaoxing wine","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"rock sugar","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"star anise","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"stick","name":"cinnamon","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"bay leaves","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"Sichuan peppercorns","note":null,"is_optional":false,"food_id":null},{"quantity":2.5,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null}]},{"name":"For the bowls","ingredients":[{"quantity":600,"unit":"g","name":"wheat noodles","note":"thick and chewy, not thin egg noodles","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"baby bok choy","note":"halved lengthways","is_optional":false,"food_id":null},{"quantity":6,"unit":"Tbsp","name":"pickled mustard greens","note":"rinsed and chopped","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"coriander","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"chilli oil","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"The broth","steps":[{"text":"Cover the beef shin with cold water in a large pot, bring it to a boil, then tip the whole lot into the sink. Rinse the meat and scrub the pot.","duration_minutes":10,"temperature":null,"tip":"This blanch is not optional. It takes out the grey scum that would otherwise cloud the broth for the next three hours."},{"text":"Melt the beef tallow in the dry pot and fry the doubanjiang over a low flame until the fat runs red and the paste smells toasted rather than sharp.","duration_minutes":3,"temperature":"low","tip":"Low and slow. Scorched bean paste tastes of ash and there is no rescuing the pot once it does."},{"text":"Add the onion, garlic, ginger, scallions and tomatoes and cook until the tomatoes have collapsed into the paste.","duration_minutes":8,"temperature":"medium","tip":null},{"text":"Return the beef, pour in the Shaoxing wine and soy sauce, and add the rock sugar, star anise, cinnamon, bay leaves and Sichuan peppercorns.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Pour in the water, bring it up to a bare simmer, and leave it barely moving until a spoon goes through the shin without resistance.","duration_minutes":150,"temperature":"low","tip":"A rolling boil emulsifies the fat and turns the broth cloudy for good. You want the surface to shiver, not bubble."},{"text":"Fish out the aromatics and the whole spices, then taste and correct for salt and sweetness.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"The bowls","steps":[{"text":"Boil the wheat noodles in a separate pot of water and drop the baby bok choy in for the final minute.","duration_minutes":5,"temperature":null,"tip":"Never cook the noodles in the broth. The starch they shed turns three hours of work gluey."},{"text":"Divide the noodles between deep bowls, ladle over the broth and beef, and finish with pickled mustard greens, coriander and a spoonful of chilli oil.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.7,"variant_titles":["{title}, Slow Cooker","Half-Spice {title}","{title} with Tendon"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- thai-green-curry-chicken.json
insert into sim.dish (slug, doc) values (
  $sd$thai-green-curry-chicken$sd$,
  $sd${"title":"Thai Green Curry with Chicken","description":"Gaeng keow wan gai. The trick is cracking the coconut cream with the paste before anything else joins — that split, oily stage is where the flavour comes from.","cuisine":"Thai","category":"Main","difficulty":"medium","prep_minutes":20,"cook_minutes":25,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":"Tbsp","name":"green curry paste","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"ml","name":"coconut milk","note":"full fat; do not shake the tin","is_optional":false,"food_id":null},{"quantity":500,"unit":"g","name":"chicken thighs","note":"boneless, sliced","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"Thai eggplant","note":"quartered; or 1 regular eggplant, cubed","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"palm sugar","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"kaffir lime leaves","note":"torn","is_optional":false,"food_id":null},{"quantity":1,"unit":"handful","name":"Thai basil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"red chilli","note":"sliced, to finish","is_optional":true,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Spoon the thick cream from the top of the coconut milk tin into a hot pan and fry the green curry paste in it until the fat splits out and the mixture darkens.","duration_minutes":5,"temperature":null,"tip":"You are looking for visible oil pooling at the edges. Rushing this leaves the curry tasting raw."},{"text":"Add the chicken and turn it through the paste until it is coated and sealed.","duration_minutes":4,"temperature":null,"tip":null},{"text":"Pour in the rest of the coconut milk with the kaffir lime leaves and bring to a bare simmer.","duration_minutes":3,"temperature":null,"tip":null},{"text":"Add the Thai eggplant and simmer until tender but not collapsing.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Season with fish sauce and palm sugar, tasting as you go — it should land salty, sweet, and hot in that order.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Take off the heat and stir through the Thai basil and sliced red chilli.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.3,"variant_titles":["Weeknight {title}","{title}, Extra Hot"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- trinidadian-corn-soup.json
insert into sim.dish (slug, doc) values (
  $sd$trinidadian-corn-soup$sd$,
  $sd${"title":"Trinidadian Corn Soup","description":"Split peas cooked to nothing, thickened with coconut milk, and loaded with corn on the cob and hand-rolled dumplings. Street food that gets made in a drum on a Saturday night.\n\nThe split peas have to collapse completely before anything else goes in. Half-cooked peas never catch up, and the soup stays thin around them.","cuisine":"Trinidadian","category":"Soup","difficulty":"medium","prep_minutes":25,"cook_minutes":80,"servings":8,"attribution":null,"ingredient_groups":[{"name":"The soup","ingredients":[{"quantity":300,"unit":"g","name":"yellow split peas","note":"picked over and rinsed","is_optional":false,"food_id":null},{"quantity":2,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"corn on the cob","note":"cut into thick rounds","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"coconut oil","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"carrots","note":"in coins","is_optional":false,"food_id":null},{"quantity":4,"unit":"sprigs","name":"thyme","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"ml","name":"coconut milk","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"scotch bonnet","note":"left whole and unpierced","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null}]},{"name":"Dumplings","ingredients":[{"quantity":200,"unit":"g","name":"plain flour","note":null,"is_optional":false,"food_id":null},{"quantity":0.5,"unit":"tsp","name":"fine salt","note":null,"is_optional":false,"food_id":null},{"quantity":100,"unit":"ml","name":"warm water","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"The soup","steps":[{"text":"Simmer the yellow split peas in the water with the thyme until they have lost their shape entirely.","duration_minutes":40,"temperature":null,"tip":"Skim the grey foam in the first five minutes. It never dissolves and it dulls the finished pot."},{"text":"Soften the onion, garlic, and carrots in the coconut oil, then tip the lot into the peas.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Add the corn on the cob rounds and lower the scotch bonnet in whole, and simmer until the corn gives to a fork.","duration_minutes":15,"temperature":null,"tip":"Unpierced, the pepper perfumes the pot and nothing more. Burst it and the whole batch belongs to it."},{"text":"Pour in the coconut milk and bring it back to a bare simmer, then season with the salt.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Dumplings","steps":[{"text":"Rub the plain flour and fine salt together and add just enough of the warm water to make a stiff dough.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Rest the dough, then roll teaspoons of it between your palms into short tapered cigars.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Drop the dumplings into the simmering soup and cook them until they float and are no longer floury in the middle.","duration_minutes":12,"temperature":null,"tip":null},{"text":"Fish the scotch bonnet out before you serve, and put the corn rounds in the bowls first so everybody gets one.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Dumplings","Saturday Night {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- tunisian-makroudh.json
insert into sim.dish (slug, doc) values (
  $sd$tunisian-makroudh$sd$,
  $sd${"title":"Makroudh","description":"Semolina diamonds around a spiced date paste, fried until they set and dropped straight into warm honey. Makes about thirty pieces and they keep for a week in a tin.\n\nSemolina dough has to rest before it can be rolled — the grains need time to drink. Skip the rest and it crumbles along every cut.","cuisine":"Tunisian","category":"Dessert","difficulty":"hard","prep_minutes":60,"cook_minutes":25,"servings":10,"attribution":null,"ingredient_groups":[{"name":"Semolina dough","ingredients":[{"quantity":500,"unit":"g","name":"coarse semolina","note":null,"is_optional":false,"food_id":null},{"quantity":150,"unit":"ml","name":"olive oil","note":"mild, not peppery","is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":120,"unit":"ml","name":"warm water","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"orange blossom water","note":null,"is_optional":false,"food_id":null}]},{"name":"Date filling","ingredients":[{"quantity":400,"unit":"g","name":"dates","note":"pitted, soft","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"cinnamon","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"orange zest","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"butter","note":"softened","is_optional":false,"food_id":null}]},{"name":"To finish","ingredients":[{"quantity":500,"unit":"ml","name":"neutral oil","note":"for frying","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"honey","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"sesame seeds","note":null,"is_optional":true,"food_id":null}]}],"step_groups":[{"name":"The dough","steps":[{"text":"Rub the olive oil into the coarse semolina with your fingertips until every grain is coated and the bowl smells nutty.","duration_minutes":5,"temperature":null,"tip":"This is the only real technique in the recipe. Oil-coated grains give a short, sandy bite; under-rubbed ones go hard."},{"text":"Sprinkle in the salt, warm water, and orange blossom water and press the mixture together without kneading it.","duration_minutes":null,"temperature":null,"tip":"Semolina has no gluten worth developing. Kneading only compacts it — gather it, do not work it."},{"text":"Cover the bowl and leave it alone while the semolina swells.","duration_minutes":120,"temperature":null,"tip":null}]},{"name":"The filling","steps":[{"text":"Work the pitted dates with the cinnamon, orange zest, and butter into a smooth, pliable paste.","duration_minutes":null,"temperature":null,"tip":null}]},{"name":"Shaping and frying","steps":[{"text":"Roll a third of the dough into a long rope, press a channel down its length with the side of your finger, and lay a rope of date paste into it.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Close the dough over the filling, flatten the log gently with your palm, and cut it on the diagonal into diamonds.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the diamonds in the neutral oil at a moderate heat, turning once, until they are set and pale gold.","duration_minutes":18,"temperature":"160°C / 320°F","tip":"Too hot and the outside colours before the inside cooks; a makroudh should be dry-crumbed in the middle, never doughy."},{"text":"Warm the honey in a wide pan and drop each piece in straight from the fryer, turning it until it is glossy.","duration_minutes":5,"temperature":null,"tip":"Hot pastry into warm honey is the whole trick. Either one cold and the honey sits on the surface instead of soaking in."},{"text":"Lift them onto a rack, scatter with the sesame seeds, and leave them to set before stacking.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":0.5,"variant_titles":["{title} with Almond Filling","Baked {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- turkish-mint-lemonade.json
insert into sim.dish (slug, doc) values (
  $sd$turkish-mint-lemonade$sd$,
  $sd${"title":"Mint Lemonade","description":"Whole lemons blitzed with mint and ice — peel included, which is where the perfume is. Strained once so it stays sharp rather than bitter.\n\nUse unwaxed lemons. If you can only get waxed ones, peel them and add a strip of zest back instead.","cuisine":"Turkish","category":"Drink","difficulty":"easy","prep_minutes":10,"cook_minutes":0,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":3,"unit":null,"name":"lemons","note":"unwaxed, quartered, seeds removed","is_optional":false,"food_id":null},{"quantity":1,"unit":"cup","name":"mint","note":"leaves picked","is_optional":false,"food_id":null},{"quantity":0.5,"unit":"cup","name":"sugar","note":"adjust to the fruit","is_optional":false,"food_id":null},{"quantity":750,"unit":"ml","name":"cold water","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"cups","name":"ice","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"pinch","name":"salt","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Remove every seed from the quartered lemons.","duration_minutes":null,"temperature":null,"tip":"One missed seed makes the whole jug bitter. This is the only fiddly part."},{"text":"Blitz the lemons with the sugar, salt, mint, ice, and half the cold water in short bursts.","duration_minutes":1,"temperature":null,"tip":"Short bursts only. Long blending pulls bitterness out of the pith."},{"text":"Strain through a coarse sieve, pressing lightly, and top up with the remaining cold water.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Taste and adjust with more sugar or lemon, then serve over ice.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["Frozen {title}","{title} with Cucumber"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- ukrainian-borscht.json
insert into sim.dish (slug, doc) values (
  $sd$ukrainian-borscht$sd$,
  $sd${"title":"Ukrainian Borscht","description":"Beet soup with a beef broth base, soured with vinegar at the end so the colour stays red rather than turning brown. Makes a large pot and improves for three days.\n\nThe vinegar is not for flavour alone — acid is what fixes the pigment. Add it too late and the pot has already gone dull.","cuisine":"Ukrainian","category":"Soup","difficulty":"medium","prep_minutes":30,"cook_minutes":120,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":800,"unit":"g","name":"beef short rib","note":"bone in","is_optional":false,"food_id":null},{"quantity":3,"unit":"L","name":"water","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"beets","note":"peeled and coarsely grated","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"carrots","note":"grated","is_optional":false,"food_id":null},{"quantity":1,"unit":null,"name":"onion","note":"diced","is_optional":false,"food_id":null},{"quantity":300,"unit":"g","name":"white cabbage","note":"shredded","is_optional":false,"food_id":null},{"quantity":3,"unit":null,"name":"potatoes","note":"cubed","is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"tomato paste","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":"Tbsp","name":"red wine vinegar","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"cloves","name":"garlic","note":"crushed","is_optional":false,"food_id":null},{"quantity":1,"unit":"bunch","name":"dill","note":"chopped, to finish","is_optional":false,"food_id":null},{"quantity":200,"unit":"g","name":"sour cream","note":"to serve","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Simmer the beef short rib in the water, skimming the foam off for the first few minutes, until the meat is tender.","duration_minutes":90,"temperature":null,"tip":"Skim properly at the start and the broth stays clear for the rest of the cook."},{"text":"Lift out the beef, pull the meat from the bone, and return it to the pot.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Fry the onion and carrots until soft, then add the beets, tomato paste, and one tablespoon of the red wine vinegar and cook down.","duration_minutes":15,"temperature":null,"tip":"Souring the beets in the pan is the insurance policy for the colour."},{"text":"Add the potatoes to the broth and cook until nearly done.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Stir in the beet mixture and the white cabbage and simmer until the cabbage is just tender.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Off the heat, stir in the crushed garlic and the remaining vinegar, then season hard.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Serve with dill and a spoonful of sour cream in each bowl.","duration_minutes":null,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title}, Meat Free","Grandmother's {title}"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- uzbek-plov.json
insert into sim.dish (slug, doc) values (
  $sd$uzbek-plov$sd$,
  $sd${"title":"Uzbek Plov","description":"One pot, built in layers and never stirred once the rice goes in: lamb browned hard, onions and matchstick carrots cooked down into a broth, then rice steamed on top until every grain is separate. Turned out onto a platter for eight.\n\nCut the carrots by hand. It is twenty tedious minutes and it is the difference between plov and orange rice pudding — a box grater turns them to mush in the broth.","cuisine":"Uzbek","category":"Main","difficulty":"medium","prep_minutes":30,"cook_minutes":95,"servings":8,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":500,"unit":"g","name":"lamb shoulder","note":"cut into 4 cm pieces","is_optional":false,"food_id":null},{"quantity":100,"unit":"ml","name":"sunflower oil","note":null,"is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"onions","note":"halved and sliced thin","is_optional":false,"food_id":null},{"quantity":600,"unit":"g","name":"carrots","note":"cut by hand into matchsticks, never grated","is_optional":false,"food_id":null},{"quantity":600,"unit":"g","name":"long-grain rice","note":"rinsed until the water runs clear","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"cumin seeds","note":"whole","is_optional":false,"food_id":null},{"quantity":1,"unit":"Tbsp","name":"coriander seeds","note":"lightly crushed","is_optional":false,"food_id":null},{"quantity":2,"unit":"heads","name":"garlic","note":"papery outer skin rubbed off, left whole","is_optional":false,"food_id":null},{"quantity":150,"unit":"g","name":"chickpeas","note":"drained, from a tin","is_optional":true,"food_id":null},{"quantity":50,"unit":"g","name":"raisins","note":null,"is_optional":true,"food_id":null},{"quantity":1.2,"unit":"L","name":"water","note":"boiling","is_optional":false,"food_id":null},{"quantity":2,"unit":"tsp","name":"salt","note":null,"is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"black pepper","note":null,"is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Heat the sunflower oil in a heavy casserole until it shimmers, then brown the lamb hard in two batches so the pan never cools.","duration_minutes":12,"temperature":null,"tip":"This is the only part of the recipe that wants a loud pan. Everything after it is quiet."},{"text":"Return all the meat, add the onions, and cook until they have gone golden and sweet at the edges.","duration_minutes":10,"temperature":null,"tip":null},{"text":"Add the carrots and let them soften without much stirring — they should still be recognisable batons when the dish is finished.","duration_minutes":8,"temperature":null,"tip":null},{"text":"Stir in the cumin seeds, coriander seeds, salt and black pepper, then pour over the boiling water and scatter in the chickpeas and raisins.","duration_minutes":null,"temperature":null,"tip":"Boiling water, not cold. Cold water drops the pan out of the browning you just paid for."},{"text":"Bury the whole garlic heads in the pan and let this base simmer uncovered until the liquid tastes strongly of everything in it and has reduced by about a third.","duration_minutes":30,"temperature":null,"tip":null},{"text":"Level the rice over the top in an even layer. Do not stir it in — from here the two halves cook separately, one boiling and one steaming.","duration_minutes":null,"temperature":null,"tip":"Add boiling water if needed so it sits about a finger's width above the rice, no more."},{"text":"Cook uncovered until the surface liquid has gone, then poke five or six holes down to the base with the handle of a wooden spoon.","duration_minutes":20,"temperature":null,"tip":"The holes let the steam up through the grain instead of pooling underneath and boiling the bottom layer."},{"text":"Mound the rice into a dome, cover the pot tightly, and steam on the lowest heat you can manage.","duration_minutes":25,"temperature":null,"tip":null},{"text":"Rest off the heat, then turn the whole thing out onto a wide platter, with the meat and the softened garlic sitting on top.","duration_minutes":10,"temperature":null,"tip":null}]}],"weight":1.1,"variant_titles":["{title} with Beef","Sunday {title}","{title} for a Crowd"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

-- vietnamese-caramel-pork.json
insert into sim.dish (slug, doc) values (
  $sd$vietnamese-caramel-pork$sd$,
  $sd${"title":"Vietnamese Caramel Pork","description":"Thit kho. Pork belly simmered in a caramel taken right to the edge of burnt, with fish sauce and coconut water. Dark, salty, and sweet in that order.\n\nThe caramel should smell almost scorched before the liquid goes in. Pale caramel makes a sweet, flat dish.","cuisine":"Vietnamese","category":"Main","difficulty":"easy","prep_minutes":15,"cook_minutes":75,"servings":4,"attribution":null,"ingredient_groups":[{"name":"","ingredients":[{"quantity":700,"unit":"g","name":"pork belly","note":"skin on, cut into 3cm pieces","is_optional":false,"food_id":null},{"quantity":4,"unit":"Tbsp","name":"sugar","note":null,"is_optional":false,"food_id":null},{"quantity":3,"unit":"Tbsp","name":"fish sauce","note":null,"is_optional":false,"food_id":null},{"quantity":400,"unit":"ml","name":"coconut water","note":null,"is_optional":false,"food_id":null},{"quantity":4,"unit":"cloves","name":"garlic","note":"sliced","is_optional":false,"food_id":null},{"quantity":2,"unit":null,"name":"shallots","note":"sliced","is_optional":false,"food_id":null},{"quantity":4,"unit":null,"name":"eggs","note":"hard boiled and peeled","is_optional":false,"food_id":null},{"quantity":1,"unit":"tsp","name":"black pepper","note":"coarsely cracked","is_optional":false,"food_id":null}]}],"step_groups":[{"name":"","steps":[{"text":"Melt the sugar in a dry heavy pot and let it go to a deep mahogany caramel without stirring.","duration_minutes":6,"temperature":null,"tip":"Swirl the pan rather than stirring. Take it one shade darker than looks wise."},{"text":"Add the garlic and shallots to the caramel — it will seize and spit — and stir until fragrant.","duration_minutes":1,"temperature":null,"tip":null},{"text":"Add the pork belly and turn it until every piece is coated and starting to colour.","duration_minutes":5,"temperature":null,"tip":null},{"text":"Pour in the coconut water and fish sauce, add the cracked black pepper, and bring to a simmer.","duration_minutes":null,"temperature":null,"tip":null},{"text":"Cook covered on a low heat until the pork is tender.","duration_minutes":50,"temperature":"low","tip":null},{"text":"Add the hard boiled eggs and cook uncovered so the sauce reduces to a glaze and the eggs stain brown.","duration_minutes":12,"temperature":null,"tip":null}]}],"weight":1,"variant_titles":["{title} with Eggs"]}$sd$::jsonb
) on conflict (slug) do update set doc = excluded.doc;

